function updatePorts(nodeId, parameters, editorConnection) {
  const ports = [];

  // Add Upload input
  ports.push({
    type: 'signal',
    plug: 'input',
    group: 'Control',
    name: 'Upload',
    displayName: 'Upload'
  });

  // Add Update input
  ports.push({
    type: 'signal',
    plug: 'input',
    group: 'Control',
    name: 'Update',
    displayName: 'Update'
  });

  // Add full data output
  ports.push({
    type: '*',
    plug: 'output',
    group: 'Data',
    name: 'data',
    displayName: 'Data'
  });

  // Add dynamic outputs based on jsonKeys parameter
  let jsonKeys = [];
  try {
    const keysParam = parameters && parameters.jsonKeys;
    if (keysParam) {
      jsonKeys = JSON.parse(keysParam);
    }
  } catch (e) {
    // Ignore parse errors
  }

  // Add output ports for each JSON key
  if (Array.isArray(jsonKeys)) {
    jsonKeys.forEach((key) => {
      ports.push({
        type: '*', // Will be inferred from the actual value
        plug: 'output',
        group: 'Data',
        name: key,
        displayName: key.replace(/([A-Z])/g, ' $1').replace(/^./, (str) => str.toUpperCase())
      });
    });
  }

  editorConnection.sendDynamicPorts(nodeId, ports);
}

function setupNodeEvents(node) {
      // Initial port update
      updatePorts(node.id, node.parameters, context.editorConnection);

      // Listen for parameter updates
      node.on('parameterUpdated', function (event) {
        if (event.name === 'jsonKeys') {
          updatePorts(node.id, node.parameters, context.editorConnection);
        }
      });
    }

