},
methods: {
  calculate: function () {
    try {
      const selected = this.getInputValue('selected spots') || [];
      const drawn = this.getInputValue('drawn numbers') || [];

      const hitNumbers = [];
      for (let i = 0; i < selected.length; i++) {
        if (drawn.includes(selected[i])) {
          hitNumbers.push(selected[i]);
