inputs.code:
{
    // Position & Transform
    x: { 
      displayName: 'X', group: 'Position', type: 'number', default: 0,
      allowConnectionsFrom: ['net.xgenia.animatetovalue', 'logic.Tween'],
      set(value) { this._internal.x = value ?? 0; this._updatePixiProperty('x', this._internal.x); } 
    },
    y: { 
      displayName: 'Y', group: 'Position', type: 'number', default: 0,
      allowConnectionsFrom: ['net.xgenia.animatetovalue', 'logic.Tween'],
      set(value) { this._internal.y = value ?? 0; this._updatePixiProperty('y', this._internal.y); } 
    },

    // Animation Control
    animationSpeed: {
      displayName: 'Animation Speed', group: 'Animation', type: 'number', default: 1,
      allowConnectionsFrom: ['net.xgenia.animatetovalue', 'logic.Tween'],
      set(speed) {
        const newSpeed = Math.max(0, parseFloat(speed) || 0);
        if (this._internal.animationSpeed !== newSpeed) {
          this._internal.animationSpeed = newSpeed;
          this._updateAnimationProperty('speed', newSpeed);
        }
      }
    },

    // Animation toggles
    loop: {
      displayName: 'Loop', group: 'Animation', type: 'boolean', default: true,
      set(value) {
        const newVal = value ?? true;
        if (this._internal.loop !== newVal) {
          this._internal.loop = newVal;
          this._updateAnimationProperty('loop', newVal);
        }
      }
    },
    autoPlay: {
      displayName: 'Auto Play', group: 'Animation', type: 'boolean', default: false,
      set(value) {
        const newVal = value ?? false;
        if (this._internal.autoPlay !== newVal) {
          this._internal.autoPlay = newVal;
          this._updateAnimationProperty('autoPlay', newVal);
        }
      }
    },

    speedMultiplier: {
      displayName: 'Speed Multiplier', group: 'Animation', type: 'number', default: 1,
      allowConnectionsFrom: ['net.xgenia.animatetovalue', 'logic.Tween'],
      set(multiplier) {
        const newMultiplier = Math.max(0, parseFloat(multiplier) || 0);
        if (this._internal.speedMultiplier !== newMultiplier) {
          this._internal.speedMultiplier = newMultiplier;
          this._updateEffectiveSpeed();
        }
      }
    },

    textureUrls: {
      displayName: 'Texture URLs', 
      group: 'Textures', 
      type: { name: 'string', codeeditor: 'json', allowEditOnly: true }, 
      default: '[]',
      set(value) {
        console.log(`[PixiAnimatedSprite ${this.id}] Setting texture URLs:`, value);
        try {
          // Parse the JSON string into an array
          const urls = typeof value === 'string' ? JSON.parse(value) : value;
          const newUrls = Array.isArray(urls) ? urls.filter(url => typeof url === 'string' && url.trim()) : [];

          console.log(`[PixiAnimatedSprite ${this.id}] Parsed URLs:`, newUrls);
          console.log(`[PixiAnimatedSprite ${this.id}] Current URLs:`, this._internal.textureUrls);

          // Always update if we have new URLs (don't skip initial setting)
          if (JSON.stringify(this._internal.textureUrls) !== JSON.stringify(newUrls) || (newUrls.length > 0 && this._internal.textures.length === 0)) {
            this._internal.textureUrls = newUrls;
            console.log(`[PixiAnimatedSprite ${this.id}] Loading ${newUrls.length} textures...`);
            this._loadTextures();
          } else {
            console.log(`[PixiAnimatedSprite ${this.id}] URLs unchanged, skipping load`);
          }
        } catch (e) {
          console.warn(`[PixiAnimatedSprite ${this.id}] Invalid texture URLs JSON:`, value, e);
          // Fallback to empty array
          if (JSON.stringify(this._internal.textureUrls) !== JSON.stringify([])) {
            this._internal.textureUrls = [];
            this._loadTextures();
          }
        }
      }
    },

    textureFiles: {
      displayName: 'Texture Files',
      group: 'Textures',
      type: '*',
      set(value) {
        // Accept single File/Blob or array of File/Blob
        const filesArray = Array.isArray(value) ? value : (value ? [value] : []);
        const validFiles = filesArray.filter(f => f && (typeof f === 'object') && (typeof f.name === 'string' || typeof f.type === 'string'));
        const changed = JSON.stringify(validFiles.map(f => f.name || 'unnamed')) !== JSON.stringify((this._internal.textureFiles || []).map(f => f.name || 'unnamed'));
        if (changed) {
          this._internal.textureFiles = validFiles;
          this._loadTextures();
        }
      }
    },

    frameRange: {
      displayName: 'Frame Range', group: 'Animation', type: { name: 'string', codeeditor: 'json', allowEditOnly: true }, default: '',
      set(value) {
        try {
          const parsed = typeof value === 'string' ? JSON.parse(value) : value;
          const next = (parsed && typeof parsed.start === 'number' && typeof parsed.end === 'number') ? { start: parsed.start, end: parsed.end } : null;
          if (JSON.stringify(this._internal.frameRange) !== JSON.stringify(next)) {
            this._internal.frameRange = next;
            this._updateAnimationProperty('frameRange', next);
          }
        } catch (e) {
          this._internal.frameRange = null;
          this._updateAnimationProperty('frameRange', null);
        }
      }
    },
    frameSequence: {
      displayName: 'Frame Sequence', group: 'Animation', type: { name: 'string', codeeditor: 'json', allowEditOnly: true }, default: '',
      set(value) {
        try {
          const parsed = typeof value === 'string' ? JSON.parse(value) : value;
          const next = Array.isArray(parsed) ? parsed.filter(n => Number.isFinite(n)).map(n => Math.max(0, Math.floor(n))) : null;
          if (JSON.stringify(this._internal.frameSequence) !== JSON.stringify(next)) {
            this._internal.frameSequence = next;
            this._updateAnimationProperty('frameSequence', next);
          }
        } catch (e) {
          this._internal.frameSequence = null;
          this._updateAnimationProperty('frameSequence', null);
        }
      }
    },

    playing: {
        displayName: 'Playing', group: 'Animation Control', type: 'boolean', default: true,
        set(value) {
            const shouldPlay = value ?? true;
            if (this._internal.playing !== shouldPlay) {
                this._internal.playing = shouldPlay;
          this._updatePlayState(shouldPlay);
        }
      }
    },

    // Signals
    play: { 
      displayName: 'Play', group: 'Signals', type: 'signal', 
      valueChangedToTrue() { this.setInputValue('playing', true); } 
    },
    stop: { 
      displayName: 'Stop', group: 'Signals', type: 'signal', 
      valueChangedToTrue() { this.setInputValue('playing', false); } 
    }
  }

