inputs.code:
{
    assetListJSON: {
      displayName: 'Asset List (JSON)',
      group: 'Assets',
      type: 'string', // JSON string: '[{"url": "path/to/image.png", "type": "texture"}, ...]'
      default: '[]',
      set(jsonString) {
        try {
          const newList = JSON.parse(jsonString);
          if (Array.isArray(newList)) {
            // Basic validation for each item
            this._internal.assetList = newList.filter(item => item && typeof item.url === 'string' && typeof item.type === 'string');
            this._internal.allAssetsLoaded = false; // Reset loaded status if list changes
            this.flagOutputDirty('progress');
            this.flagOutputDirty('allAssetsLoaded');
            if (this._internal.triggerPreload && this._internal.assetList.length > 0) { // Only restart if trigger was active and list is not empty
              this._startPreloading(); 
            }
          } else {
            console.warn('[AssetPreloaderNode] Invalid assetListJSON: Not an array.');
            this._internal.assetList = [];
          }
        } catch (e) {
          console.error('[AssetPreloaderNode] Error parsing assetListJSON:', e);
          this._internal.assetList = [];
        }
      }
    },
    startPreload: {
      displayName: 'Start Preload',
      group: 'Control',
      type: 'boolean', // Pulse input
      set(value) {
        if (value && !this._internal.preloading && this._internal.assetList.length > 0) {
          this._internal.triggerPreload = true;
          this._startPreloading();
        } else if (!value) {
            this._internal.triggerPreload = false; // Allow re-triggering if pulsed false then true
        }
      }
    }
  }

