    maxZoom: { displayName: 'Max Zoom', group: 'Zoom', type: 'number', default: 10, set(v){ this._internal.maxZoom = v ?? 10; this._internal.zoom = this._clampZoom(this._internal.zoom); this._updateCamera(true); } },
