    'bounds.width': { displayName: 'Bounds Width', group: 'Limits', type: 'number', default: 1000, set(v){
      if (!this._internal.bounds) this._internal.bounds = { x: 0, y: 0, width: 1000, height: 1000 };
      const val = Number.isFinite(v) ? Math.max(1, v) : 1000;
      this._internal.bounds.width = val;
      this._updateCamera(true);
    } },
    'bounds.height': { displayName: 'Bounds Height', group: 'Limits', type: 'number', default: 1000, set(v){
