pixi.Container.fullDefinition:
name: 'pixi.Container',
displayNodeName: 'Pixi Container',
category: 'Pixi',
getReactComponent() {
  return PixiContainerComponent;
},
initialize() {
  this.pixiComponentHandle = null;
  this.containerObject = null;

  this._internal = {
    scaleX: 1, scaleY: 1, rotation: 0,
    pivotX: 0, pivotY: 0, alpha: 1, visible: true, zIndex: 0,
    sortableChildren: false, interactive: false, eventMode: 'auto', cursor: null,
    backgroundColor: null, backgroundAlpha: DEFAULT_BACKGROUND_ALPHA,
    // Animation state
    tickerEnabled: false,
    tickerSpeed: 1,
    animationType: 'none',
    customAnimationCode: '',
    width: undefined,
    height: undefined,
    clipToBounds: false

inputs.code:
{
    // Visibility
    visible: {
      displayName: 'Visible',
      group: 'Display',
      type: 'boolean',
      default: true,
      set(value) {
        this._internal.visible = !!value;
        this.updateDisplay();
      }
    },

    // Position
    position: {
      displayName: 'Position',
      group: 'Display',
      type: {
        name: 'enum',
        enums: ['top-left', 'top-right', 'bottom-left', 'bottom-right', 'custom']
      },
      default: 'top-left',
      set(value) {
        this._internal.position = value;
        this.updateDisplay();
      }
    },

    customX: {
      displayName: 'Custom X',
      group: 'Display',
      type: 'number',
      default: 10,
      set(value) {
        this._internal.customX = value ?? 10;
        if (this._internal.position === 'custom') {
          this.updateDisplay();
        }
      }
    },

    customY: {
      displayName: 'Custom Y',
      group: 'Display',
      type: 'number',
      default: 10,
      set(value) {
        this._internal.customY = value ?? 10;
        if (this._internal.position === 'custom') {
          this.updateDisplay();
        }
      }
    },

    // Appearance
    backgroundColor: {
      displayName: 'Background Color',
      group: 'Appearance',
      type: 'color',
      default: '#000000',
      set(value) {
        const colorHex = typeof value === 'string' ? parseInt(value.replace("#", ""), 16) : value;
        this._internal.backgroundColor = colorHex;
        this.updateDisplay();
      }
    },

    backgroundAlpha: {
      displayName: 'Background Alpha',
      group: 'Appearance',
      type: 'number',
      default: 0.7,
      min: 0,
      max: 1,
      set(value) {
        this._internal.backgroundAlpha = value ?? 0.7;
        this.updateDisplay();
      }
    },

    textColor: {
      displayName: 'Text Color',
      group: 'Appearance',
      type: 'color',
      default: '#00FF00',
      set(value) {
        const colorHex = typeof value === 'string' ? parseInt(value.replace("#", ""), 16) : value;
        this._internal.textColor = colorHex;
        this.updateDisplay();
      }
    },

    fontSize: {
      displayName: 'Font Size',
      group: 'Appearance',
      type: 'number',
      default: 12,
      min: 8,
      max: 24,
      set(value) {
        this._internal.fontSize = value ?? 12;
        this.updateDisplay();
      }
    },

    padding: {
      displayName: 'Padding',
      group: 'Appearance',
      type: 'number',
      default: 10,
      min: 0,
      max: 20,
      set(value) {
        this._internal.padding = value ?? 10;
        this.updateDisplay();
      }
    },

    // Display Options
    showFPS: {
      displayName: 'Show FPS',
      group: 'Display Options',
      type: 'boolean',
      default: true,
      set(value) {
        this._internal.showFPS = !!value;
        this.updateDisplay();
      }
    },

    showDrawCalls: {
      displayName: 'Show Draw Calls',
      group: 'Display Options',
      type: 'boolean',
      default: true,
      set(value) {
        this._internal.showDrawCalls = !!value;
        this.updateDisplay();
      }
    },

    showTextureCount: {
      displayName: 'Show Texture Count',
      group: 'Display Options',
      type: 'boolean',
      default: true,
      set(value) {
        this._internal.showTextureCount = !!value;
        this.updateDisplay();
      }
    },

    showObjectCount: {
      displayName: 'Show Object Count',
      group: 'Display Options',
      type: 'boolean',
      default: true,
      set(value) {
        this._internal.showObjectCount = !!value;
        this.updateDisplay();
      }
    },

    showUpdateInfo: {
      displayName: 'Show Update Info',
      group: 'Display Options',
      type: 'boolean',
      default: true,
      set(value) {
        this._internal.showUpdateInfo = !!value;
        this.updateDisplay();
      }
    },

    showMemoryUsage: {
      displayName: 'Show Memory Usage',
      group: 'Display Options',
      type: 'boolean',
      default: true,
      set(value) {
        this._internal.showMemoryUsage = !!value;
        this.updateDisplay();
      }
    },

    // Performance
    updateInterval: {
      displayName: 'Update Interval (ms)',
      group: 'Performance',
      type: 'number',
      default: 100,
      min: 16,
      max: 1000,
      set(value) {
        this._internal.updateInterval = value ?? 100;
        this.restartUpdateTimer();
      }
    },

    usePerformanceMonitor: {
      displayName: 'Use Performance Monitor',
      group: 'Performance',
      type: 'boolean',
      default: true,
      set(value) {
        this._internal.usePerformanceMonitor = !!value;
        if (value) {
          this._initPerformanceMonitor();
        } else {
          this._cleanupPerformanceMonitor();
        }
      }
    },

    showStatsJSPanel: {
      displayName: 'Show Stats.js Panel',
      group: 'Performance',
      type: 'boolean',
      default: false,
      set(value) {
        this._internal.showStatsJSPanel = !!value;
        this._updateStatsJSPanel();
      }
    },

    // Custom Info
    customKey1: {
      displayName: 'Custom Key 1',
      group: 'Custom Info',
      type: 'string',
      default: '',
      set(value) {
        this._internal.customKey1 = value;
        this.updateDisplay();
      }
    },

    customValue1: {
      displayName: 'Custom Value 1',
      group: 'Custom Info',
      type: '*',
      default: '',
      set(value) {
        if (this._internal.customKey1) {
          this._stats.customValues[this._internal.customKey1] = value;
          this.updateDisplay();
        }
      }
    },

    customKey2: {
      displayName: 'Custom Key 2',
      group: 'Custom Info',
      type: 'string',
      default: '',
      set(value) {
        this._internal.customKey2 = value;
        this.updateDisplay();
      }
    },

    customValue2: {
      displayName: 'Custom Value 2',
      group: 'Custom Info',
      type: '*',
      default: '',
      set(value) {
        if (this._internal.customKey2) {
          this._stats.customValues[this._internal.customKey2] = value;
          this.updateDisplay();
        }
      }
    },

    customKey3: {
      displayName: 'Custom Key 3',
      group: 'Custom Info',
      type: 'string',
      default: '',
      set(value) {
        this._internal.customKey3 = value;
        this.updateDisplay();
      }
    },

    customValue3: {
      displayName: 'Custom Value 3',
      group: 'Custom Info',
      type: '*',
      default: '',
      set(value) {
        if (this._internal.customKey3) {
          this._stats.customValues[this._internal.customKey3] = value;
          this.updateDisplay();
        }
      }
    },

    // Debug Controls
    reconnectPixiApp: {
      displayName: 'Reconnect to PIXI App',
      group: 'Debug Controls',
      type: 'signal',
      valueChangedToTrue() {
        this.disconnectFromPixiApp();
        setTimeout(() => this.connectToPixiApp(), 100);
      }
    },

    resetFPSHistory: {
      displayName: 'Reset FPS History',
      group: 'Debug Controls', 
      type: 'signal',
      valueChangedToTrue() {
        this._fpsHistory = [];
        this._frameCount = 0;
        this._lastFPSTime = performance.now();
        this.flagOutputDirty('averageFPS');
        this.flagOutputDirty('minFPS');
        this.flagOutputDirty('maxFPS');
      }
    }
  }

outputs.code:
{
    currentFPS: {
      displayName: 'Current FPS',
      group: 'Performance',
      type: 'number',
      getter() { return this._stats.fps; }
    },

    averageFPS: {
      displayName: 'Average FPS',
      group: 'Performance',
      type: 'number',
      getter() {
        if (this._fpsHistory.length === 0) return 0;
        const sum = this._fpsHistory.reduce((a, b) => a + b, 0);
        return Math.round(sum / this._fpsHistory.length);
      }
    },

    minFPS: {
      displayName: 'Min FPS',
      group: 'Performance',
      type: 'number',
      getter() {
        if (this._fpsHistory.length === 0) return 0;
        return Math.min(...this._fpsHistory);
      }
    },

    maxFPS: {
      displayName: 'Max FPS',
      group: 'Performance',
      type: 'number',
      getter() {
        if (this._fpsHistory.length === 0) return 0;
        return Math.max(...this._fpsHistory);
      }
    },

    drawCalls: {
      displayName: 'Draw Calls',
      group: 'Rendering',
      type: 'number',
      getter() { return this._stats.drawCalls; }
    },

    objectCount: {
      displayName: 'Object Count',
      group: 'Scene',
      type: 'number',
      getter() { return this._stats.objectCount; }
    },

    memoryUsageMB: {
      displayName: 'Memory Usage (MB)',
      group: 'System',
      type: 'number',
      getter() { return Math.round(this._stats.memoryUsage / 1024 / 1024); }
    },

    // Debug outputs
    pixiAppConnected: {
      displayName: 'PIXI App Connected',
      group: 'Debug',
      type: 'boolean',
      getter() { return !!(this._pixiApp && this._pixiApp.ticker && this._tickerFn); }
    },

    fpsSource: {
      displayName: 'FPS Source',
      group: 'Debug',
      type: 'string',
      getter() { 
        if (this._pixiApp && this._pixiApp.ticker && this._tickerFn) {
          return 'PIXI Ticker';
        } else if (this._fallbackActive) {
          return 'RequestAnimationFrame';
        } else {
          return 'No Measurement';
        }
      }
    },

    frameCount: {
      displayName: 'Frame Count',
      group: 'Debug',
      type: 'number',
      getter() { return this._frameCount || 0; }
    }
  }

inputs.code:
{
    target: {
      displayName: 'Target Node',
      group: 'Target',
      type: 'node',
      set(value) {
        this._internal.target = value || null;
        this._resolveTarget();
      }
    },

    // Control
    autoStart: { displayName: 'Auto Start', group: 'Control', type: 'boolean', default: false, set(v) { this._internal.autoStart = !!v; } },
    start: { displayName: 'Start', group: 'Control', type: 'signal', valueChangedToTrue() { this._startTween(); } },
    restart: { displayName: 'Restart', group: 'Control', type: 'signal', valueChangedToTrue() { this._restartTween(); } },
    stop: { displayName: 'Stop', group: 'Control', type: 'signal', valueChangedToTrue() { this._killTween(); } },
    pause: { displayName: 'Pause', group: 'Control', type: 'signal', valueChangedToTrue() { if (this._tween) this._tween.pause(); } },
    resume: { displayName: 'Resume', group: 'Control', type: 'signal', valueChangedToTrue() { if (this._tween) this._tween.resume(); } },
    applyNow: { displayName: 'Apply Now', group: 'Control', type: 'signal', valueChangedToTrue() { this._startTween(); } },

    // Property mapping
    xProp: { displayName: 'X Property', group: 'Properties', type: 'string', default: 'x', set(v) { this._internal.xProp = v || 'x'; } },
    yProp: { displayName: 'Y Property', group: 'Properties', type: 'string', default: 'y', set(v) { this._internal.yProp = v || 'y'; } },
    rotationProp: { displayName: 'Rotation Property', group: 'Properties', type: 'string', default: 'rotation', set(v) { this._internal.rotationProp = v || 'rotation'; } },

    // Velocities
    useCurrentVelocity: { displayName: 'Use Current Velocity', group: 'Inertia', type: 'boolean', default: false, set(v) { this._internal.useCurrentVelocity = !!v; } },
    vx: { displayName: 'Vx (px/s)', group: 'Inertia', type: 'number', default: 0, set(v) { this._internal.vx = v || 0; } },
    vy: { displayName: 'Vy (px/s)', group: 'Inertia', type: 'number', default: 0, set(v) { this._internal.vy = v || 0; } },
    rotationVelocity: { displayName: 'Rotation Velocity', group: 'Inertia', type: 'number', default: 0, set(v) { this._internal.rotationVelocity = v || 0; } },

    // Resistance
    resistance: { displayName: 'Resistance', group: 'Inertia', type: 'number', default: 200, set(v) { this._internal.resistance = Math.max(0, v || 0); } },
    rotationResistance: { displayName: 'Rotation Resistance', group: 'Inertia', type: 'number', default: 300, set(v) { this._internal.rotationResistance = Math.max(0, v || 0); } },

    // Bounds
    minX: { displayName: 'Min X', group: 'Bounds', type: 'number', default: null, set(v) { this._internal.minX = (v === '' || v == null) ? null : v; } },
    maxX: { displayName: 'Max X', group: 'Bounds', type: 'number', default: null, set(v) { this._internal.maxX = (v === '' || v == null) ? null : v; } },
    minY: { displayName: 'Min Y', group: 'Bounds', type: 'number', default: null, set(v) { this._internal.minY = (v === '' || v == null) ? null : v; } },
