name: 'pixi.KeyboardInput',
category: 'pixi-visual',
color: 'orange',
docs: 'https://docs.xgenia.com/nodes/pixi-keyboardinput',
inputs: {
    keys: {
        type: 'string',
        default: 'ArrowLeft,ArrowRight,ArrowUp,ArrowDown,Space,w,a,s,d',
        displayName: 'Keys to Track (comma separated)'
    }
},
outputs: {
    onKeyDown: { type: 'signal', displayName: 'Key Down' },
    onKeyUp: { type: 'signal', displayName: 'Key Up' },
    lastKeyPressed: { type: 'string', displayName: 'Last Key Pressed' },
    // Common movement maps
    up: { type: 'boolean', displayName: 'Up (W/ArrowUp)' },
    down: { type: 'boolean', displayName: 'Down (S/ArrowDown)' },
    left: { type: 'boolean', displayName: 'Left (A/ArrowLeft)' },
    right: { type: 'boolean', displayName: 'Right (D/ArrowRight)' },
    space: { type: 'boolean', displayName: 'Space' }
},
methods: {
    register() {
        this._trackedKeys = new Set();
        this._activeKeys = new Set();
        this._parseKeys(this.inputs.keys);

        this._handleKeyDown = this._handleKeyDown.bind(this);
        this._handleKeyUp = this._handleKeyUp.bind(this);

        window.addEventListener('keydown', this._handleKeyDown);
        window.addEventListener('keyup', this._handleKeyUp);
    },
    _parseKeys(keyString) {
        this._trackedKeys.clear();
        if (keyString) {
            keyString.split(',').forEach(k => this._trackedKeys.add(k.trim()));
        }
    },
    _updateCommonOutputs() {
        this.setOutputs({
            up: this._activeKeys.has('w') || this._activeKeys.has('W') || this._activeKeys.has('ArrowUp'),
            down: this._activeKeys.has('s') || this._activeKeys.has('S') || this._activeKeys.has('ArrowDown'),
            left: this._activeKeys.has('a') || this._activeKeys.has('A') || this._activeKeys.has('ArrowLeft'),
            right: this._activeKeys.has('d') || this._activeKeys.has('D') || this._activeKeys.has('ArrowRight'),
            space: this._activeKeys.has(' ') || this._activeKeys.has('Space')

