helpers.code:
function resolveMatter() {
  if (typeof window !== 'undefined') {
    if (window.Matter) return window.Matter;
    if (window.__MATTER) return window.__MATTER;
  }
  try {
    // eslint-disable-next-line global-require
    const m = require('matter-js');
    if (typeof window !== 'undefined') window.__MATTER = m;
    return m;
  } catch (e) {
    return null;
  }
}

function getBoundsSafe(obj) {
  try { return obj.getBounds(true); } catch (e) { return new PIXI.Rectangle(obj.x || 0, obj.y || 0, 1, 1); }
}

function requestRenderNow(displayObject) {
  if (!displayObject) return;
  if (typeof window !== 'undefined' && window.__PIXI_UPDATE_MANAGER) {
    try { window.__PIXI_UPDATE_MANAGER.requestRender(); } catch (e) {}
    return;
  }
  let root = displayObject;
  while (root && root.parent) root = root.parent;
  try { root?.pixiApp?.render?.(); } catch (e) {}
}

function getMatterManagerForApp(app) {
  if (!app) return null;
  if (typeof window === 'undefined') return null;
  if (!window.__MATTER_MANAGERS) window.__MATTER_MANAGERS = new Map();
  if (window.__MATTER_MANAGERS.has(app)) return window.__MATTER_MANAGERS.get(app);

  const Matter = resolveMatter();
  if (!Matter) return null;

  const engine = Matter.Engine.create();
  const bodies = new Set(); // nodes register here
  let tickerFn = null;

  const manager = {
    app,
    Matter,
    engine,
    bodies,
    tickerFn,
    setGravity(x, y) {
      engine.gravity.x = x || 0;
      engine.gravity.y = y || 0;
    },
    ensureTicker() {
      if (!app?.ticker) return;
      if (tickerFn) tickerRemove(app.ticker, tickerFn);
      tickerFn = (ticker) => {
        const deltaMs = typeof ticker?.deltaMS === 'number' ? ticker.deltaMS : (1000 / 60);
        try { Matter.Engine.update(engine, deltaMs); } catch (e) {}
        // Update all display objects bound to bodies
        bodies.forEach((node) => {
          if (!node?._internal?.targetResolved || !node?._internal?.body) return;
          const body = node._internal.body;
          const obj = node._internal.targetResolved;
          obj.x = body.position.x;
          obj.y = body.position.y;
          obj.rotation = body.angle;
        });
      };
      try { tickerAdd(app.ticker, tickerFn); } catch (e) {}
      manager.tickerFn = tickerFn;
    },
    teardownIfEmpty() {
      if (bodies.size === 0) {
        try { if (tickerFn) tickerRemove(app?.ticker, tickerFn); } catch (e) {}
        tickerFn = null;
      }
    },
    onCollisionCallbacksAttached: false
  };

  window.__MATTER_MANAGERS.set(app, manager);
  return manager;
}

