    emitterConfigJSON: {
      displayName: 'Emitter Config (JSON)', group: 'Emitter Config', type: { name: 'string', codeeditor: 'json' },
      default: JSON.stringify({ // A complete default config that works with @pixi/particle-emitter
        "lifetime": { "min": 0.5, "max": 1.5 },
        "frequency": 0.01,
        "spawnChance": 1,
        "particlesPerWave": 1,
        "emitterLifetime": -1,
        "maxParticles": 500,
        "addAtBack": false,
        "pos": { "x": 0, "y": 0 },
        "behaviors": [
          {
            "type": "alpha",
            "config": {
              "alpha": {
                "list": [
                  { "value": 0.8, "time": 0 },
                  { "value": 0.1, "time": 1 }
                ]
              }
            }
          },
          {
            "type": "moveSpeed",
            "config": {
              "speed": {
                "list": [
                  { "value": 200, "time": 0 },
                  { "value": 50, "time": 1 }
                ],
