              }
            }
          }
        ]
      }, null, 2),
      set(jsonString) {
        this._internal.emitterConfigJSON = jsonString;
        this._recreateEmitter();
      }
    },

    // --- Emitter Control ---
    emit: {
      displayName: 'Emit Particles', group: 'Control', type: 'boolean', default: true, // Often start emitting by default
      set(value) {
        const shouldEmit = value ?? false;
        if (this._internal.emit !== shouldEmit) {
          this._internal.emit = shouldEmit;
          if (this.pixiEmitter) {
            this.pixiEmitter.emit = this._internal.emit;
          }
        }
      }
    },
    startEmitter: {
      displayName: 'Start Emitting', group: 'Control', type: 'signal',
      valueChangedToTrue() {
        // A signal is an EDGE, not a value. Assigning emit=true does nothing whenever emit is
        // already true, because the emit setter below guards on change — and `emit` declares
        // default:true. On top of that, a finite-lifetime emitter latches _emitterComplete
        // once emitterAge passes emitterLifetime and never clears it on its own, so the
        // burst presets (coinBurst 0.1s, explosion 0.05s) fired once at mount and could
        // never fire again. reset() zeroes emitterAge, clears that latch and drops stale
        // particles; it has existed since this class was written and nothing ever called it.
        this._internal.emit = true;
        if (this.pixiEmitter) {
          this.pixiEmitter.reset();
          this.pixiEmitter.emit = true;
        }
        this.setInputValue('emit', true);
      }
    },
    stopEmitter: {
      displayName: 'Stop Emitting (Graceful)', group: 'Control', type: 'signal',
      valueChangedToTrue() {
        // Stop producing new particles; the live ones finish their lifetime.
        // Written through to the emitter as well as the port, for the same reason
        // startEmitter is: the setter is change-guarded and can swallow this.
        this._internal.emit = false;
        if (this.pixiEmitter) this.pixiEmitter.emit = false;
        this.setInputValue('emit', false);
      }
    },
    stopAndClear: {
      displayName: 'Stop & Clear All Particles', group: 'Control', type: 'signal',
      valueChangedToTrue() {
        this._internal.emit = false;
        if (this.pixiEmitter) {
          this.pixiEmitter.emit = false;
          // reset(), not cleanup(): cleanup() only hides the particles and leaves emitterAge
          // and the _emitterComplete latch untouched, so a finite-lifetime emitter that had
          // already expired stayed expired and the next startEmitter was dead on arrival.
          this.pixiEmitter.reset();
          if (typeof window.__PIXI_UPDATE_EVENT?.dispatchEvent === 'function') {
            window.__PIXI_UPDATE_EVENT.dispatchEvent(new CustomEvent('pixiUpdate'));
          }
        }
        this.setInputValue('emit', false);
      }
    },
    autoUpdate: {
      displayName: 'Auto Update (Ticker)', group: 'Advanced', type: 'boolean', default: true,
      set(value) {
        const auto = value ?? true;
        if (this._internal.autoUpdate !== auto) {
          this._internal.autoUpdate = auto;
          this._manageEmitterTicker();
        }
      }
    },

    // Particle count control
    particleCount: {
      displayName: 'Particle Count', group: 'Control', type: 'number', default: 500,
      set(value) {
        const count = Math.max(1, Math.min(1000, value ?? 500)); // Clamp between 1-1000
        if (this._internal.particleCount !== count) {
          this._internal.particleCount = count;
          this._updateParticleCount();
        }
      }
    },

    // Quick particle count presets
    setParticleCountLow: {
      displayName: 'Set Low Count (50)', group: 'Control', type: 'signal',
      valueChangedToTrue() { this.setInputValue('particleCount', 50); }
    },
    setParticleCountMedium: {
      displayName: 'Set Medium Count (200)', group: 'Control', type: 'signal',
      valueChangedToTrue() { this.setInputValue('particleCount', 200); }
    },
    setParticleCountHigh: {
      displayName: 'Set High Count (500)', group: 'Control', type: 'signal',
      valueChangedToTrue() { this.setInputValue('particleCount', 500); }
    },
    setParticleCountMax: {
      displayName: 'Set Max Count (1000)', group: 'Control', type: 'signal',
      valueChangedToTrue() { this.setInputValue('particleCount', 1000); }
    },

    // Preset configurations for common effects
    presetConfig: {
      displayName: 'Preset Config', group: 'Emitter Config',
      type: {
        name: 'enum',
        enums: [
          { label: 'Custom', value: 'custom' },
          { label: 'Fire', value: 'fire' },
          { label: 'Sparkle', value: 'sparkle' },
          { label: 'Smoke', value: 'smoke' },
          { label: 'Explosion', value: 'explosion' },
