function ensureConfigCompatibilityInline(config) {
          // Deep clone the config to avoid modifying the original
          const compatibleConfig = JSON.parse(JSON.stringify(config));

          // Ensure all required properties exist with proper defaults
          if (!compatibleConfig.lifetime) {
            compatibleConfig.lifetime = { min: 0.5, max: 1.5 };
          }
          if (!compatibleConfig.frequency) {
            compatibleConfig.frequency = 0.01;
          }
          if (!compatibleConfig.spawnChance) {
            compatibleConfig.spawnChance = 1;
          }
          if (!compatibleConfig.particlesPerWave) {
            compatibleConfig.particlesPerWave = 1;
          }
          if (!compatibleConfig.emitterLifetime) {
            compatibleConfig.emitterLifetime = -1;
          }
          if (!compatibleConfig.maxParticles) {
            compatibleConfig.maxParticles = 100;
          }
          if (!compatibleConfig.addAtBack) {
            compatibleConfig.addAtBack = false;
          }
          if (!compatibleConfig.pos) {
            compatibleConfig.pos = { x: 0, y: 0 };
          }
          if (!compatibleConfig.behaviors) {
            compatibleConfig.behaviors = [];
          }

          // Ensure behaviors have proper structure
          compatibleConfig.behaviors = compatibleConfig.behaviors.map(behavior => {
            if (!behavior.type) {
              console.warn(`[PixiEmitterNode] Behavior missing type:`, behavior);
              return null;
            }
            if (!behavior.config) {
              console.warn(`[PixiEmitterNode] Behavior missing config:`, behavior);
              return null;
            }
            return behavior;
          }).filter(Boolean); // Remove null behaviors

          // If no valid behaviors, add a basic one
          if (compatibleConfig.behaviors.length === 0) {
            compatibleConfig.behaviors.push({
              type: "alpha",
              config: {
                alpha: {
                  list: [
                    { value: 0.8, time: 0 },
                    { value: 0.1, time: 1 }
                  ]
                }
              }
            });
          }

          // Additional safety checks for @pixi/particle-emitter v5.0.8
          // Ensure all behavior configs have the required structure
          compatibleConfig.behaviors.forEach(behavior => {
            if (behavior.type === 'alpha' && behavior.config.alpha) {
              if (!behavior.config.alpha.list || !Array.isArray(behavior.config.alpha.list)) {
                behavior.config.alpha.list = [
                  { value: 0.8, time: 0 },
                  { value: 0.1, time: 1 }
                ];
              }
            }
            if (behavior.type === 'scale' && behavior.config.scale) {
              if (!behavior.config.scale.list || !Array.isArray(behavior.config.scale.list)) {
                behavior.config.scale.list = [
                  { value: 0.4, time: 0 },
                  { value: 0.1, time: 1 }
                ];
              }
            }
            if (behavior.type === 'moveSpeed' && behavior.config.speed) {
              if (!behavior.config.speed.list || !Array.isArray(behavior.config.speed.list)) {
                behavior.config.speed.list = [
                  { value: 200, time: 0 },
                  { value: 50, time: 1 }
                ];
              }
            }
            if (behavior.type === 'rotationStatic' && behavior.config) {
              if (typeof behavior.config.min !== 'number') {
                behavior.config.min = 0;
              }
              if (typeof behavior.config.max !== 'number') {
                behavior.config.max = 360;
              }
            }
            if (behavior.type === 'spawnShape' && behavior.config) {
              if (!behavior.config.type) {
                behavior.config.type = 'circle';
              }
              if (!behavior.config.data) {
                behavior.config.data = { x: 0, y: 0, radius: 10 };
              }
            // Validate new behavior types
            if (behavior.type === 'gravity' && behavior.config) {
              if (typeof behavior.config.value !== 'number' && typeof behavior.config.y !== 'number') {
                behavior.config.value = 0;
              }
            }
            if (behavior.type === 'direction' && behavior.config) {
              if (typeof behavior.config.minAngle !== 'number') behavior.config.minAngle = 0;
              if (typeof behavior.config.maxAngle !== 'number') behavior.config.maxAngle = 360;
            }
            if (behavior.type === 'rotationSpeed' && behavior.config) {
              if (typeof behavior.config.min !== 'number') behavior.config.min = 0;
              if (typeof behavior.config.max !== 'number') behavior.config.max = 0;
            }
            if (behavior.type === 'color' && behavior.config && behavior.config.color) {
              if (!behavior.config.color.list || !Array.isArray(behavior.config.color.list)) {
                behavior.config.color.list = [{ value: '#FFFFFF', time: 0 }];
              }
            }
            if (behavior.type === 'blendMode' && behavior.config) {
              if (!behavior.config.blendMode) behavior.config.blendMode = 'NORMAL';
            }
            if (behavior.type === 'acceleration' && behavior.config) {
              if (typeof behavior.config.x !== 'number') behavior.config.x = 0;
              if (typeof behavior.config.y !== 'number') behavior.config.y = 0;
            }
            }
          });

          console.log(`[PixiEmitterNode] Config compatibility check passed`);
          return compatibleConfig;
        }

