name: 'pixi.Spine',
displayNodeName: 'Pixi Spine',
category: 'Pixi|Animation',

docs: "https://docsapp.xgenia.com/nodes/pixi-nodes/pixi-spine/",
shortDesc: 'Professional Spine skeleton animation for 2D skeletal animations.',

getReactComponent() {
  return PixiSpineComponent;
},

initialize() {
  console.log(`[PixiSpine ${this.id}] Initializing node...`);
  this.pixiObject = null;

  this._internal = {
    // Transform
    x: 0, y: 0, alpha: 1, rotation: 0, scaleX: 1, scaleY: 1,
    width: undefined, height: undefined,
    visible: true, zIndex: 0,
    // Layout / scaling to avoid morphing
    fitMode: 'contain', // 'contain' default for intuitive width/height behavior
    preserveAspect: true,
    baseBounds: null,

    // Interaction (PIXI v8)
    eventMode: 'auto', // 'none' | 'auto' | 'passive' | 'static' | 'dynamic'
    interactiveChildren: false,

    // Spine Assets
    skeletonUrl: '', atlasUrl: '', scale: 1, autoUpdate: true,
    assetVersion: 0,

    // Animation Control
    currentAnimation: '', currentTrack: 0, animationSpeed: 1, loop: true,
    playing: true, timeScale: 1, mixDuration: 0.2,
    currentSkin: '',

    // Simplified: advanced features removed for clarity

    // Events
    eventListeners: new Map(),

