inputs.code:
{
    // ─── THE PANEL IS THE PRODUCT (2026-08-15) ──────────────────────────────────
    // Before today the Dimensions group held SEVEN controls, two of them labelled
    // "Width", spread over three different coordinate systems (DOM box / canvas /
    // design box). User: "It is very confusing and inhuman, and it does not align
    // well". The keys are unchanged — nothing stored migrates — but the SURFACE now
    // reads like every other XGENIA node:
    //
    //   Dimensions   Size Mode, Width, Height       ← identical to Group/Text/Image
    //   Scaling      Scale Content, Design Width, Design Height
    //
    // `width`/`height` are the design box and live under Scaling, where a second
    // pair of size numbers is expected rather than confusing. fitPadding is gone:
    // it was a fifth number nobody asked for, its label overflowed its own row, and
    // the standard Padding ports already inset the canvas.
    width: {
      index: 21,
      displayName: 'Design Width', group: 'Scaling', type: 'number', default: 800,
      tooltip: 'The width you author your Pixi content at. Only used when Scale Content is on.',
      set(value) {
        value = this._toDesignPixels(value, 'Design Width');
        if (value === null) return;
        this._internal.width = value; this.props.options.width = value;
        // Routed through _applyStageFit: under a fit this IS the design box, so
        // changing it re-maps rather than just re-tagging.
        if (this.pixiApp && this.pixiApp.stage) this._applyStageFit();
        this.updatePixiAppProperties();
      }
    },
    height: {
      index: 22,
      displayName: 'Design Height', group: 'Scaling', type: 'number', default: 600,
      tooltip: 'The height you author your Pixi content at. Only used when Scale Content is on.',
      set(value) {
        value = this._toDesignPixels(value, 'Design Height');
        if (value === null) return;
        this._internal.height = value; this.props.options.height = value;
        if (this.pixiApp && this.pixiApp.stage) this._applyStageFit();
        this.updatePixiAppProperties();
      }
    },
    // ─── RESPONSIVE SCALING ─────────────────────────────────────────────────────
    // (2026-08-14, user: "lets say I resize the window and there are icons… they do not
    // stay within the window and take the full space… you just calculate spacing or
    // something but its really confusing and complex")
    //
    // Before this, the ONLY responsive path in the whole PIXI system lived on
    // PixiReelController (autoLayout + fitMode), which recomputed every cell's pixel size
    // per column on each pass. Two problems with that. First, it made a slot-game
    // orchestrator a prerequisite for a Stage full of anything to be responsive — a Stage
    // with ReelColumns and no controller silently never scaled, with no warning anywhere.
    // Second, per-child pixel maths is where the drift lives: every consumer has to agree
    // about cell size, and they did not.
    //
    // The Stage owns the canvas and the ResizeObserver, so it is the honest home for this.
    // The model is a DESIGN RESOLUTION: author your content at a fixed size, and the Stage
    // maps that box onto whatever the canvas actually is by scaling its root container.
    // Children keep their authored coordinates and need no resize logic at all — this is
    // O(1) per resize instead of O(nodes), and nothing can disagree about the result.
    fitMode: {
      index: 20,
      // The enums carried no labels, so the panel showed the raw values — a dropdown
      // reading "none / fit / fill / stretch". Say what each one does instead.
      displayName: 'Scale Content', group: 'Scaling',
      type: {
        name: 'enum',
        enums: [
          { value: 'none', label: "Off — don't scale" },
          { value: 'fit', label: 'Fit — show all of it' },
          { value: 'fill', label: 'Fill — cover, crop edges' },
          { value: 'stretch', label: 'Stretch — exact, distorts' }
        ]
      },
      default: 'none',
      tooltip: 'Scales your Pixi content to whatever size the Stage ends up. Leave Off for 1:1 pixels.',
      set(value) {
        // none    — 1:1 pixels, no scaling (historical behaviour, still the default)
        // fit     — uniform scale, whole design box visible, letterboxed
        // fill    — uniform scale, canvas fully covered, overflow cropped
        // stretch — non-uniform, fills exactly, aspect ratio not preserved
        this._internal.fitMode = value || 'none';
        this._applyStageFit();
      }
    },
    backgroundColor: {
      displayName: 'Bg Color', group: 'Appearance', type: 'color', default: '#1099bb',
      set(value) {
        const colorHex = typeof value === 'string' ? parseInt(value.replace("#", ""), 16) : value;
        this._internal.backgroundColor = colorHex; this.props.options.backgroundColor = colorHex; this.updatePixiAppProperties();
      }
    },
    backgroundAlpha: {
      displayName: 'Bg Alpha', group: 'Appearance', type: 'number', default: 1, min: 0, max: 1,
      set(value) { this._internal.backgroundAlpha = value; this.props.options.backgroundAlpha = value; this.updatePixiAppProperties(); }
    },
    transparentBackground: {
      displayName: 'Transparent', group: 'Appearance', tooltip: 'Draw with no background at all, so whatever is behind the Stage shows through.', type: 'boolean', default: false,
      set(value) {
        this._internal.transparentBackground = !!value;
        this.props.options.transparentBackground = !!value;

        if (value) {
          // Set transparent background - alpha to 0, no background color
          this._internal.backgroundAlpha = 0;
          this.props.options.backgroundAlpha = 0;
        } else {
          // Restore opaque background
          this._internal.backgroundAlpha = 1;
          this.props.options.backgroundAlpha = 1;
        }
        this.updatePixiAppProperties();
      }
    },
    resolution: {
      displayName: 'Resolution', group: 'Rendering', type: 'number', default: 1,
      set(value) { this._internal.resolution = value || 1; this.props.options.resolution = value || 1; this.updatePixiAppProperties(); }
    },
    antialias: {
      displayName: 'Antialias', group: 'Rendering', type: 'boolean', default: true,
