helpers.code:
function _normaliseDomDimension(value) {
  if (value === null || value === undefined || value === '') return undefined;
  // Already canonical.
  if (typeof value === 'object' && value.value !== undefined) {
    const n = typeof value.value === 'number' ? value.value : parseFloat(String(value.value));
    if (!isFinite(n)) return undefined;
    return { value: n, unit: String(value.unit || '%') };
  }
  // A bare number is a percentage here — the port's declared defaultUnit, and its default of 100
  // means "fill the parent".
  if (typeof value === 'number') return isFinite(value) ? { value: value, unit: '%' } : undefined;
  if (typeof value === 'string') {
    const m = /^\s*(-?\d*\.?\d+)\s*(%|px|vw|vh)?\s*$/.exec(value);
    if (m) return { value: parseFloat(m[1]), unit: m[2] || '%' };
    // Anything else (calc(), auto, a keyword) cannot be a {value,unit}. Keep it verbatim rather
    // than discarding the author's intent; the component passes it to CSS, which may understand it.
    return value;
  }
  return undefined;
}

