                        // ─── A CELEBRATION PARKED ON SYMBOLS NOBODY LANDED (2026-08-14) ──────
                        // Same unbounded-park shape as the stop signal, with one extra hazard.
                        // If the reels were force-stopped because their stop data never arrived,
                        // they are showing whatever symbols they happened to land on — NOT the
                        // result. Celebrating cells computed from a result that arrives after
                        // that would highlight positions the player cannot see a win in. So the
                        // park is released only when the reels stopped on real data; otherwise
                        // it is dropped with a warning that names the actual cause.
                        console.log('[PixiReelController] celebrateWin arrived before winningCells data — queueing until data arrives');
                        this._celebrationArmed = true;
                        clearTimeout(this._celebrationArmTimer);
                        var selfC = this;
                        this._celebrationArmTimer = setTimeout(function () {
                            selfC._celebrationArmTimer = null;
                            if (!selfC._celebrationArmed) return;
                            selfC._celebrationArmed = false;
                            console.warn('[PixiReelController] celebrateWin was queued but no winningCells arrived within '
                                + CELEBRATION_ARM_TIMEOUT_MS + ' ms — dropping the celebration. '
                                + 'Wire the maths win data to winningCells / winningLines, or to spinResult.');
                        }, CELEBRATION_ARM_TIMEOUT_MS);
                        return;
