        winningCells: {
            type: 'array', displayName: 'Winning Cells', group: 'Win Celebration: Data',
            // 2026-08-14: the flush used to live inline here, making this PORT the only way a
            // parked celebration could ever run — the same single-flush-site defect the stop
            // park had. Three other places write _internal.winningCells (spinResult's
            // _processSpinResult, the winningLines port, and this one); only this one released
            // the park. _setWinningCells is now the shared writer.
            set: function (v) { this._setWinningCells(v); }
        },
        winningLines: {
            type: 'array', displayName: 'Winning Lines', group: 'Win Celebration: Data',
            set: function (v) {
                var lines = Array.isArray(v) ? v : [];
                this._internal.winningLines = lines;
                var flat = [];
                for (var i = 0; i < lines.length; i++) {
                    var line = lines[i];
                    var lineIdx = line.lineIndex !== undefined ? line.lineIndex : i;
                    var payout = line.payout !== undefined ? line.payout : '';
                    var posList = line.positions || (Array.isArray(line) ? line : []);
                    var mid = Math.floor(posList.length / 2);

                    for (var p = 0; p < posList.length; p++) {
                        var pData = posList[p];
                        var isMid = (p === mid);
                        var cellPayout = isMid ? payout : '';

                        if (Array.isArray(pData)) {
                            flat.push({
                                line: lineIdx,
                                row: pData[0],
                                col: pData[1],
                                payout: cellPayout,
                                isMiddle: isMid
                            });
                        } else if (typeof pData === 'object') {
                            flat.push(Object.assign({ 
                                line: lineIdx, 
                                payout: cellPayout, 
                                isMiddle: isMid 
                            }, pData));
                        }
                    }
                }
