        _getConnectedColumns: function () {
            return this._internal.columns.filter(function (c) { return c != null; });
        },

        // Debounced auto-layout — self-healing on cold start.
        // 2026-06-11 (reel-system review wshq2880k — root cause of the
        // "must refresh for the reels to work" + "reels jump to center on the
        // first spin" reports): the first layout used to fire ONCE after 50ms
