                    self.flagOutputDirty('currentSymbols');
                    self.sendSignalOnOutput('onCascadeComplete');
                } else {
                    setTimeout(checkComplete, 50);
                }
            };
            setTimeout(checkComplete, 100);
        },

        /**
         * Warm the texture cache for every symbol URL, WITHOUT the two side effects.
         *
         * (2026-08-16) _preloadTextures is the only bulk PIXI.Assets.load in the whole reel
         * system, and it had exactly two callers: the `initialize` and `preloadTextures` signal
         * ports. Nothing drives either — the scaffolder only INSPECTS whether `initialize` is
         * wired and, when it is not, pushes an advisory string; it never makes the connection.
         * So the one piece of code that fills the cache never ran in a scaffolded game.
         *
         * Symbols still appeared, because a cell that misses the cache falls back to a per-cell
         * Assets.load — so the cost was a late first paint and a burst of cache warnings at spin
         * start, not a blank reel. That is worth fixing on its own, and it does not need a wire:
         * the moment symbolImages arrives we know every URL the game will use.
         *
         * The emit and the distribute stay OUT of this function deliberately. `texturesLoaded`
         * is an output a graph may gate its start-up chain on, and firing it from a data setter
         * — possibly repeatedly — would change the meaning of that signal. Assets.load dedupes
         * by URL, so warming again after a second write costs nothing.
         */
        _warmTextures: function () {
            var urls = this._collectSymbolUrls();
            for (var i = 0; i < urls.length; i++) {
                try {
                    if (typeof PIXI !== 'undefined' && PIXI.Assets) {
                        PIXI.Assets.load(urls[i]).catch(function () { /* the cell path reports it */ });
                    }
                } catch (e) { /* warming is best-effort; never break a data write */ }
            }
        },

        _collectSymbolUrls: function () {
            var images = this._internal.symbolImages || [];
            var videos = this._internal.symbolVideos || [];
            var urls = [];
            var urlMap = {};
            [images, videos].forEach(function (list) {
                if (!Array.isArray(list)) return;
                for (var i = 0; i < list.length; i++) {
                    var url = list[i];
                    if (url && typeof url === 'string' && !urlMap[url]) {
                        urlMap[url] = true;
                        urls.push(url);
                    }
                }
            });
            return urls;
        },

        _preloadTextures: function () {
            var urls = this._collectSymbolUrls();

            if (urls.length === 0) {
                this._distributeInitialData();
                this.sendSignalOnOutput('texturesLoaded');
                return;
            }

            var self = this;
            var loadedCount = 0;
            var total = urls.length;

            var checkComplete = function () {
                loadedCount++;
                if (loadedCount >= total) {
                    self._distributeInitialData();
                    self.sendSignalOnOutput('texturesLoaded');
                }
            };

            urls.forEach(function(url) {
                try {
                    if (typeof PIXI !== 'undefined' && PIXI.Assets) {
                        PIXI.Assets.load(url).then(checkComplete).catch(function (err) {
                            console.warn('[PixiReelController] Failed to preload:', url, err);
                            checkComplete();
                        });
                    } else {
                        checkComplete();
                    }
                } catch (e) {
                    checkComplete();
                }
            });
        },

        _getAllCurrentSymbols: function () {
            var columns = this._getConnectedColumns();
            var result = [];
            for (var c = 0; c < columns.length; c++) {
                if (typeof columns[c]._getCurrentVisibleSymbols === 'function') {
                    result.push(columns[c]._getCurrentVisibleSymbols());
                } else {
                    result.push([]);
                }
            }
            return result;
        },

        _onNodeDeleted: function () {
            // 2026-06-11 (reel-system review wshq2880k): cancel ALL scheduled
            // work on teardown, not just celebration timers. Critical now that
            // _maybeAutoLayout retries via a chained _autoLayoutTimer — a node
            // deleted mid-retry would otherwise keep firing setTimeout against
            // a torn-down node. Also clear the stagger timers (they mutate cell
            // .y positions) and reset the spin flag.
            clearTimeout(this._autoLayoutTimer);
            this._unregisterStageListener();
            this._clearTimers();
            this._clearCelebrationTimers();
            // FIX (2026-07-01, trace 1782908019565): also cancel the completion-watch /
            // watchdog poll, else it keeps firing setTimeout against a torn-down node.
            clearTimeout(this._completionWatchTimer);
            this._completionWatchTimer = null;
            this._stopRequestedTime = null;
            this._spinning = false;
        }
    }

