function findIn(obj, key) {
                if (!obj || typeof obj !== 'object') return null;
                // Priority 1: Direct key
                if (obj[key] !== undefined) return obj[key];
                // Priority 2: Keys within known sub-objects
                if (obj.spinResults && obj.spinResults[key] !== undefined) return obj.spinResults[key];
                if (obj.spinResult && obj.spinResult[key] !== undefined) return obj.spinResult[key];
                // Priority 3: Deep search
                for (var k in obj) {
                    if (obj[k] && typeof obj[k] === 'object' && k !== 'reelStrips') {
                        var found = findIn(obj[k], key);
                        if (found) return found;
                    }
                }
                return null;
