prototypeExtensions.code:
{
    registerInputIfNeeded: function (name) {
      if (this.hasInput(name)) return;
      if (name.startsWith('freeSpinsRewardCount')) {
        const count = parseInt(name.replace('freeSpinsRewardCount', ''), 10);
        if (isNaN(count) || count < 1) return;

        this.registerInput(name, {
          type: 'number',
          displayName: `Free Spins for ${count} Symbols`,
          group: 'Custom Free Spins Rewards',
          set: function (value) {
            if (value === undefined || value === null || value === '') {
              delete this._internal.customFreeSpinsRewards[count];
              return;
            }
            const num = Number(value);
            if (Number.isNaN(num) || !Number.isFinite(num)) return;
            this._internal.customFreeSpinsRewards[count] = num;
          }
        });
      }
    },
    calculateFreeSpinsStates: function () {
      try {
        const reels = this._internal.engineReels;
        let currentFreeSpins = this._internal.currentFreeSpins;
        const betAmount = this._internal.betAmount;
        let capital = this._internal.capital;
        let totalBets = this._internal.totalBets;
        let totalFreeSpinsWon = this._internal.totalFreeSpinsWon;
        const blockedReels = this._internal.blockedReels;
        const freeSpinsSymbol = this._internal.freeSpinsSymbol;

        // Validate inputs
        if (!Array.isArray(reels) || reels.length === 0) {
          throw new Error('Engine reels array is required and cannot be empty');
        }

        if (!blockedReels || typeof blockedReels !== 'string') {
          throw new Error('Blocked reels must be a valid comma-separated string');
        }

        // Parse blocked reels
        const blockedReelIndices = blockedReels.split(',').map((idx) => {
          const parsed = Number(idx.trim());
          if (isNaN(parsed)) {
            throw new Error(`Invalid blocked reel index: "${idx.trim()}"`);
          }
          return parsed;
        });

        // Apply the main logic
        if (currentFreeSpins > 0) {
          capital += betAmount;
          totalBets -= betAmount;
          currentFreeSpins--;
        }

        let freeSpinsSymbolCount = 0;
        const currentFreeSpinsLines = [];

        for (let reelIdx = 0; reelIdx < reels.length; reelIdx++) {
          if (blockedReelIndices.includes(reelIdx)) continue;

          const reel = reels[reelIdx];
          if (!Array.isArray(reel)) continue;

          for (let lineIdx = 0; lineIdx < reel.length; lineIdx++) {
            const symbol = reel[lineIdx];
            if (symbol === freeSpinsSymbol) {
              freeSpinsSymbolCount++;
              currentFreeSpinsLines.push({
                symbols: [symbol],
                positions: [[lineIdx, reelIdx]]
              });
              break; // Count only once per reel
            }
          }
        }

        let won = 0;
        const override = this._internal.customFreeSpinsRewards[freeSpinsSymbolCount];
        if (typeof override === 'number' && Number.isFinite(override)) {
          won = override;
        } else {
          won = evaluateFreeSpinsRewardFormula(
            this._internal.freeSpinsRewardFormula || DEFAULT_FREE_SPINS_REWARD_FORMULA,
            freeSpinsSymbolCount
          );
        }

        const currentFreeSpinsWon = won;
        totalFreeSpinsWon += won;
        currentFreeSpins += won;

        // Store results
        this._internal.capital = capital;
        this._internal.totalBets = totalBets;
        this._internal.currentFreeSpins = currentFreeSpins;
        this._internal.freeSpinsSymbolCount = freeSpinsSymbolCount;
        this._internal.currentFreeSpinsLines = currentFreeSpinsLines;
        this._internal.currentFreeSpinsWon = currentFreeSpinsWon;
        this._internal.totalFreeSpinsWon = totalFreeSpinsWon;
        this._internal.completed = true;

        // Update inspect data
        this._internal.inspectData = {
          inputReels: reels,
          blockedReels: blockedReels,
          blockedReelIndices: blockedReelIndices,
          freeSpinsSymbol: freeSpinsSymbol,
          freeSpinsSymbolCount: freeSpinsSymbolCount,
          currentFreeSpinsLines: currentFreeSpinsLines,
          calculatedWon: won,
          freeSpinsRewardFormula: this._internal.freeSpinsRewardFormula,
          customFreeSpinsRewards: { ...this._internal.customFreeSpinsRewards },
          capital: capital,
          totalBets: totalBets,
          currentFreeSpins: currentFreeSpins,
          currentFreeSpinsWon: currentFreeSpinsWon,
          totalFreeSpinsWon: totalFreeSpinsWon
        };

        // Flag outputs as dirty
        this.flagOutputDirty('capital');
        this.flagOutputDirty('totalBets');
        this.flagOutputDirty('currentFreeSpins');
        this.flagOutputDirty('freeSpinsSymbolCount');
        this.flagOutputDirty('currentFreeSpinsWon');
        this.flagOutputDirty('totalFreeSpinsWon');
        this.flagOutputDirty('currentFreeSpinsLines');
      } catch (error) {
        console.error('Calculate Free Spins States Error:', error.message);

        // Update inspect data with error
        this._internal.inspectData = {
          error: error.message
        };

        // Reset results
        this._internal.freeSpinsSymbolCount = 0;
        this._internal.currentFreeSpinsWon = 0;
        this._internal.completed = false;
        this.flagOutputDirty('capital');
        this.flagOutputDirty('totalBets');
        this.flagOutputDirty('currentFreeSpins');
        this.flagOutputDirty('freeSpinsSymbolCount');
        this.flagOutputDirty('currentFreeSpinsWon');
        this.flagOutputDirty('totalFreeSpinsWon');
        this.flagOutputDirty('currentFreeSpinsLines');
      } finally {
        // Send completed signal
        this.sendSignalOnOutput('Done');
      }
    }
  }

helpers.code:
function evaluateFreeSpinsRewardFormula(formula, x) {
  try {
    const result = evaluate(formula, {
      x: x,
      pi: Math.PI,
      e: Math.E
    });

    if (typeof result !== 'number' || Number.isNaN(result) || !Number.isFinite(result)) {
      throw new Error(`Formula must evaluate to a finite number, got: ${result}`);
    }

    return result;
  } catch (error) {
    throw new Error(`Free spins reward formula error: ${error.message}`);
  }
}

function parseBlockedReelsCount(blockedReels) {
  if (!blockedReels || typeof blockedReels !== 'string') return 0;

  const blockedSet = new Set();
  blockedReels.split(',').forEach((idx) => {
    const parsed = Number(idx.trim());
    if (!Number.isNaN(parsed)) {
      blockedSet.add(parsed);
    }
  });

  return blockedSet.size;
}

function getMaxFreeSpinsSymbolCount(parameters) {
  const reels = Array.isArray(parameters.engineReels) ? parameters.engineReels : [];
  const reelCount = reels.length || 5;
  const blockedCount = parseBlockedReelsCount(parameters.blockedReels);
  return Math.max(reelCount - blockedCount, 1);
}

function updatePorts(nodeId, parameters, editorConnection) {
  const maxCount = getMaxFreeSpinsSymbolCount(parameters || {});
  const formula = (parameters && parameters.freeSpinsRewardFormula) || DEFAULT_FREE_SPINS_REWARD_FORMULA;

  const ports = [];

  for (let count = 1; count <= maxCount; count++) {
    let def = 0;
    try {
      def = evaluateFreeSpinsRewardFormula(formula, count);
    } catch (e) {
      def = 0;
    }

    ports.push({
      type: 'number',
      plug: 'input',
      group: 'Custom Free Spins Rewards',
      name: `freeSpinsRewardCount${count}`,
      displayName: `Free Spins for ${count} Symbols`,
      default: def
    });
  }

  editorConnection.sendDynamicPorts(nodeId, ports);
}

function setupNodeEvents(node) {
      updatePorts(node.id, node.parameters, context.editorConnection);

      node.on('parameterUpdated', function (event) {
        if (event.name === 'engineReels' || event.name === 'blockedReels' || event.name === 'freeSpinsRewardFormula') {
          updatePorts(node.id, node.parameters, context.editorConnection);
        }
      });
    }

