    doCalculation: function () {
      this._internal.hasScheduledCalculation = false;

      try {
        const { winningLines, betAmount, wildSymbol, paytable, paylines } = this._internal;

        // Validate inputs
        if (!Array.isArray(winningLines)) {
          throw new Error('Winning lines must be an array');
        }

        if (betAmount <= 0) {
          this.handleSuccess(0, []);
          return;
        }

        if (!paytable || typeof paytable !== 'object') {
          throw new Error('Paytable must be a valid object');
        }

        if (!Array.isArray(paylines) || paylines.length === 0) {
          throw new Error('Paylines must be a non-empty array');
        }

        let currentSpinWinnings = 0;
        const winningLinesDetails = [];

        for (const winLine of winningLines) {
          const linePayout = this.checkPayline(winLine, betAmount, wildSymbol, paytable, paylines);

          if (linePayout > 0) {
            currentSpinWinnings += linePayout;
            winningLinesDetails.push({
              line: winLine[0],
              symbols: winLine[1],
              positions: this.calculateSymbolsPosition(winLine, paylines),
              payout: linePayout
            });
          }
        }

        this.handleSuccess(currentSpinWinnings, winningLinesDetails);
      } catch (error) {
        this.handleError(error.message);
      }
    },
    checkPayline: function (winLine, betAmount, wildSymbol, paytable, paylines) {
      const payoutMultiplier = winLine[1].length;
      const betAmountPerLine = betAmount / paylines.length;

      let payoutSymbol = null;
      for (const symbol of winLine[1]) {
        if (symbol !== wildSymbol) {
          payoutSymbol = symbol;
          break;
        }
      }

      if (payoutSymbol in paytable && payoutMultiplier in paytable[payoutSymbol]) {
        return Math.round(betAmountPerLine * paytable[payoutSymbol][payoutMultiplier]);
      }

      return 0;
    },
    calculateSymbolsPosition: function (winLine, paylines) {
      const lineIndex = winLine[0] - 1;
      const sequenceLength = winLine[1].length;
      const positions = [];
      const lineToCheck = paylines[lineIndex];

      for (let i = 0; i < sequenceLength; i++) {
        const [col, row] = lineToCheck[i];
        positions.push([row, col]);
      }

      return positions;
    },
    handleSuccess: function (currentSpinWinnings, winningLinesDetails) {
      // Store the results
      this._internal.spinWinnings = currentSpinWinnings;
      this._internal.winningLinesDetails = winningLinesDetails;

      // Update inspect data
      this._internal.inspectData = {
        winningLines: this._internal.winningLines,
        betAmount: this._internal.betAmount,
        wildSymbol: this._internal.wildSymbol,
        paytable: this._internal.paytable,
        paylines: this._internal.paylines,
        spinWinnings: currentSpinWinnings,
        winningLinesDetails: winningLinesDetails,
        totalWinningLines: winningLinesDetails.length
      };

      // Flag output as dirty
      this.flagOutputDirty('spinWinnings');
      this.flagOutputDirty('winningLinesDetails');

      // Send signal
      this.sendSignalOnOutput('Done');
    },
