        winningLines: this._internal.winningLines,
        betAmount: this._internal.betAmount,
        wildSymbol: this._internal.wildSymbol,
        paytable: this._internal.paytable,
        paylines: this._internal.paylines
      };

      // Set result to 0 and empty array on error
      this._internal.spinWinnings = 0;
      this._internal.winningLinesDetails = [];
      this.flagOutputDirty('spinWinnings');
      this.flagOutputDirty('winningLinesDetails');

      // Still send signal even on error
      this.sendSignalOnOutput('Done');
    }
  }

