{
    scheduleCascade: function () {
      if (!this._internal.hasScheduledCascade) {
        this._internal.hasScheduledCascade = true;
        this.scheduleAfterInputsHaveUpdated(this.doCascade.bind(this));
      }
    },
    doCascade: function () {
      this._internal.hasScheduledCascade = false;

      try {
        const inputReels = this._internal.inputReels;
        const winDetails = this._internal.winningLinesDetails;
        const symbolWeights = this._internal.symbolWeights;

        if (!Array.isArray(inputReels) || inputReels.length === 0) {
          throw new Error('Reels must be a non-empty array of columns');
        }
        const columnSize = inputReels.length;
        const rowSize = Array.isArray(inputReels[0]) ? inputReels[0].length : 0;
        if (rowSize === 0 || !inputReels.every((col) => Array.isArray(col) && col.length === rowSize)) {
          throw new Error('All columns in reels must be arrays of equal length');
        }

        // Build a set of positions to clear from winning lines details
        // Expected position format: [row, col]. Also accept {row, col}.
        const positionsToClear = new Set();
        let totalPositions = 0;
        if (Array.isArray(winDetails)) {
          for (const item of winDetails) {
            const positions = Array.isArray(item?.positions) ? item.positions : [];
            for (const pos of positions) {
              let row, col;
              if (Array.isArray(pos) && pos.length >= 2) {
                row = Number(pos[0]);
                col = Number(pos[1]);
              } else if (pos && typeof pos === 'object') {
                row = Number(pos.row);
                col = Number(pos.col);
              }
              if (
                Number.isInteger(row) &&
                Number.isInteger(col) &&
                row >= 0 &&
                col >= 0 &&
                col < columnSize &&
                row < rowSize
              ) {
                const key = col + ':' + row;
                if (!positionsToClear.has(key)) {
                  positionsToClear.add(key);
                  totalPositions++;
                }
              }
            }
          }
        }

        // Prepare baseReel according to Weighted Reels dynamic mode algorithm
        // If symbolWeights provided and valid: replicate symbols relative to min weight
        // Else: derive unique symbols from current reels and use uniform selection
        let baseReel = [];
        let symbolWeightsRelativeToMin = [];
        if (
          Array.isArray(symbolWeights) &&
          symbolWeights.length > 0 &&
          symbolWeights.every((w) => typeof w === 'number' && w > 0)
        ) {
          const minWeight = Math.min(...symbolWeights);
          symbolWeightsRelativeToMin = symbolWeights.map((w) => Math.ceil(w / minWeight));
          for (let i = 1; i <= symbolWeights.length; i++) {
            const reps = symbolWeightsRelativeToMin[i - 1];
            for (let r = 0; r < reps; r++) baseReel.push(i);
          }
        } else {
          const unique = new Set();
          for (const col of inputReels) {
            for (const s of col) {
              if (typeof s === 'number' && s > 0) unique.add(s);
            }
          }
          baseReel = Array.from(unique);
          if (baseReel.length === 0) {
            throw new Error('Cannot infer symbols for refill');
          }
        }

        // PROVABLY FAIR (2026-06-23): seed the refill RNG from the Seeds input
        // (ISAAC) so cascade refills are reproducible/auditable from the seed.
        // Falls back to Math.random() when Seeds isn't wired (no regression).
        function SeededRandom(seed) {
          this.seed = seed % 2147483647;
          if (this.seed <= 0) this.seed += 2147483646;
        }
        SeededRandom.prototype.next = function () {
          this.seed = (this.seed * 16807) % 2147483647;
          return this.seed;
        };
        SeededRandom.prototype.nextFloat = function () {
          return (this.next() - 1) / 2147483646;
        };
        const seeds = this._internal.seeds;
        const cascadeRng = (Array.isArray(seeds) && seeds.length > 0) ? new SeededRandom(seeds[0]) : null;
        function pickSymbol() {
          const rand = cascadeRng ? cascadeRng.nextFloat() : Math.random();
          const idx = Math.floor(rand * baseReel.length);
          return baseReel[idx];
        }

        const outputReels = [];
        for (let c = 0; c < columnSize; c++) {
          const col = inputReels[c];
          const kept = [];
          for (let r = 0; r < rowSize; r++) {
            const key = c + ':' + r;
            if (!positionsToClear.has(key)) kept.push(col[r]);
          }
          const empties = rowSize - kept.length;
          const topFill = [];
          for (let i = 0; i < empties; i++) {
            topFill.push(pickSymbol());
          }
          outputReels.push(topFill.concat(kept));
        }

        this._internal.outputReels = outputReels;

        this._internal.inspectData = {
          rowSize: rowSize,
          columnSize: columnSize,
          clearedPositions: totalPositions,
          usedSymbolWeights: Array.isArray(symbolWeights) && symbolWeights.length > 0,
          symbolWeightsRelativeToMin: symbolWeightsRelativeToMin,
          baseReelLength: baseReel.length
        };

        this.flagOutputDirty('reels');
        this.sendSignalOnOutput('Done');
      } catch (error) {
        console.error('Cascade The Reels Error:', error.message);
        this._internal.outputReels = [];
        this.flagOutputDirty('reels');
        this._internal.inspectData = { error: error.message };
        this.sendSignalOnOutput('Done');
      }
    }
  }

