    doCheck: function () {
      this._internal.hasScheduledCheck = false;

      try {
        const reels = this._internal.reels;
        const winningSymbol = this._internal.winningSymbol;

        if (!Array.isArray(reels) || reels.length === 0) {
          throw new Error('Reels must be a non-empty array');
