        if (!Number.isFinite(winningSymbol)) {
          throw new Error('Winning symbol must be a valid number');
        }

        // Validate each reel (column) is an array
        if (!reels.every((reel) => Array.isArray(reel))) {
          throw new Error('Each reel must be an array');
        }

        const reelsCount = reels.length;
        let matchingColumns = 0;
        const positions = [];

        for (let col = 0; col < reels.length; col++) {
          const reel = reels[col];
          let colHasSymbol = false;
          for (let row = 0; row < reel.length; row++) {
            if (reel[row] === winningSymbol) {
              positions.push([row, col]);
              colHasSymbol = true;
            }
          }
          if (colHasSymbol) matchingColumns += 1;
        }

        const isJackpot = matchingColumns === reelsCount;

        this.handleSuccess(isJackpot, reelsCount, matchingColumns, positions);
      } catch (error) {
        this.handleError(error.message);
