{
    scheduleFetch: function () {
      // Guard: if locked, don't regenerate
      if (this._reelStripsLocked && this._internal.reelStrips && this._internal.reelStrips.length > 0) {
        return;
      }
      if (!this._internal.hasScheduledFetch) {
        this._internal.hasScheduledFetch = true;
        this.scheduleAfterInputsHaveUpdated(this.doFetch.bind(this));
      }
    },
    doFetch: function () {
      this._internal.hasScheduledFetch = false;

      // Build the URL with query parameters
      const baseUrl = 'https://engine-typescript.vercel.app/api/v2/slot/generate-reel-strips';
      const params = new URLSearchParams({
        seed: this._internal.seed.toString(),
        rows: this._internal.rows.toString(),
        columns: this._internal.columns.toString(),
        weightFormula: this._internal.weightFormula
      });
      const url = `${baseUrl}?${params.toString()}`;

      this.doExternalFetch(url);
    },
    doExternalFetch: function (url) {
      if (typeof _xgenia_cloud_runtime_version === 'undefined') {
        // Running in browser
        const xhr = new XMLHttpRequest();
        this._xhr = xhr;

        xhr.open('GET', url, true);
        xhr.setRequestHeader('Accept', 'application/json');

        xhr.onreadystatechange = () => {
          if (xhr.readyState === 4) {
            delete this._xhr;

            if (xhr.status >= 200 && xhr.status < 300) {
              try {
                const response = JSON.parse(xhr.responseText);
                this.handleSuccess(response);
              } catch (e) {
                this.handleError('Failed to parse response JSON');
              }
            } else {
              this.handleError(`HTTP ${xhr.status}: ${xhr.statusText}`);
            }
          }
        };

        xhr.onerror = () => {
          delete this._xhr;
          this.handleError('Network error occurred');
        };

        xhr.send();
      } else {
        // Running in cloud runtime
        fetch(url, {
          method: 'GET',
          headers: {
            Accept: 'application/json'
          }
        })
          .then((response) => {
            if (response.ok) {
              return response.json();
            } else {
              throw new Error(`HTTP ${response.status}: ${response.statusText}`);
            }
          })
          .then((data) => {
            this.handleSuccess(data);
          })
          .catch((error) => {
            this.handleError(error.message);
          });
      }
    },
    handleSuccess: function (response) {
      // Store the response data
      // The API response format: {"message":"reel strips generated successfully","reelStrips":[[...]]}
      // If slotSize is not provided, calculate it from the input parameters and reel strips
      this._internal.slotRows = response.slotSize?.rows || this._internal.rows;
      this._internal.slotColumns = response.slotSize?.columns || this._internal.columns;
      this._internal.reelStrips = response.reelStrips || [];

      // If slotSize wasn't provided but we have reel strips, derive the columns from the number of strips
      if (!response.slotSize && this._internal.reelStrips.length > 0) {
        this._internal.slotColumns = this._internal.reelStrips.length;
      }

      // Update inspect data
      this._internal.inspectData = {
        message: response.message,
        slotSize: {
          rows: this._internal.slotRows,
          columns: this._internal.slotColumns
        },
        reelStrips: this._internal.reelStrips,
        reelStripsCount: this._internal.reelStrips.length
      };

      // Flag outputs as dirty
      this.flagOutputDirty('slotRows');
      this.flagOutputDirty('slotColumns');
      this.flagOutputDirty('reelStrips');

      // Send success signal
      this.sendSignalOnOutput('success');
    },
    handleError: function (errorMessage) {
      console.error('Generate Reel Strips Error:', errorMessage);

      // Update inspect data with error
      this._internal.inspectData = {
        error: errorMessage
      };

      // Send failure signal
      this.sendSignalOnOutput('failure');
    }
  }

