{
    registerInputIfNeeded: function (name) {
      if (this.hasInput(name)) return;

      if (name.startsWith('symbolWeight')) {
        const indexOneBased = parseInt(name.replace('symbolWeight', ''), 10);
        if (isNaN(indexOneBased) || indexOneBased < 1) return;
        const index = indexOneBased - 1;

        this.registerInput(name, {
          type: 'number',
          displayName: `Symbol ${indexOneBased} Custom Weight`,
          group: 'Custom Weights',
          set: function (value) {
            // Allow undefined/null to mean "use formula default"
            if (value === undefined || value === null || value === '') {
              delete this._internal.customWeights[index];
              return;
            }
            const num = Number(value);
            if (isNaN(num)) return;
            this._internal.customWeights[index] = num;
          }
        });
      }
    },
    scheduleGenerate: function () {
      if (!this._internal.hasScheduledGenerate) {
        this._internal.hasScheduledGenerate = true;
        this.scheduleAfterInputsHaveUpdated(this.doGenerate.bind(this));
      }
    },
    doGenerate: function () {
      this._internal.hasScheduledGenerate = false;

      try {
        const N = this._internal.numberOfSymbols;
        const formula = this._internal.weightFormula || 'exp(-x / 15)';

        // Base weights from formula, using 1-based x per requirements
        const baseWeights = Array.from({ length: N }, (_, i) => {
          const x = i + 1;
          try {
            return evaluateFormula(formula, x);
          } catch (e) {
            throw new Error(
              `Generate Symbol Weights: weightFormula "${formula}" is not a valid math expression in x (failed at x=${x}: ${e.message}). Use a mathjs expression such as "exp(-x / 15)", "10 - x", or "1 / x" — a bare word like "exponential" is NOT valid. Alternatively set per-symbol weights via the symbolWeight1..${N} ports.`
            );
          }
        });

        // Apply custom overrides if provided per symbol
        const finalWeights = baseWeights.map((w, i) => {
          const override = this._internal.customWeights[i];
          return typeof override === 'number' ? override : w;
        });

        const totalWeight = finalWeights.reduce((a, b) => a + b, 0);
        if (totalWeight === 0) {
          throw new Error(
            `Generate Symbol Weights: total weight is zero — every symbol would have 0 probability, so reel strips can't be generated and the spin chain stops here (Done never fires → downstream reels never stop). Cause: weightFormula "${formula}" evaluates to 0 for all ${N} symbols, OR all symbolWeight1..${N} overrides are 0. Set a non-degenerate formula (e.g. "exp(-x / 15)") or non-zero custom weights.`
          );
        }

        const normalizedBaseWeights = finalWeights.map((weight) => (weight / totalWeight) * 100);

        this.handleSuccess(baseWeights, finalWeights, totalWeight, normalizedBaseWeights);
      } catch (error) {
        this.handleError(error.message);
      }
    },
    handleSuccess: function (baseWeights, finalWeights, totalWeight, normalizedBaseWeights) {
      // Store the calculated data
      this._internal.baseWeights = baseWeights;
      this._internal.finalWeights = finalWeights;
      this._internal.totalBaseWeight = totalWeight;
      this._internal.normalizedBaseWeights = normalizedBaseWeights;

      // Update inspect data
      this._internal.inspectData = {
        numberOfSymbols: this._internal.numberOfSymbols,
        weightFormula: this._internal.weightFormula,
        baseWeights: baseWeights,
        finalWeights: finalWeights,
        totalWeight: totalWeight,
        normalizedBaseWeights: normalizedBaseWeights
      };

      // Flag outputs as dirty
      this.flagOutputDirty('normalizedBaseWeights');

      // Send success signal
      this.sendSignalOnOutput('Done');
    },
    handleError: function (errorMessage) {
      console.error('Generate Symbol Weights Error:', errorMessage);

      // Update inspect data with error
      this._internal.inspectData = {
        error: errorMessage,
        numberOfSymbols: this._internal.numberOfSymbols,
        weightFormula: this._internal.weightFormula
      };

      // Still send signal even on error
      this.sendSignalOnOutput('Done');
    }
