prototypeExtensions.code:
{
    generateReelStrips: function () {
      // Guard: if locked, don't regenerate
      if (this._reelStripsLocked && this._internal.reelStrips.length > 0) {
        // Still fire Done so downstream doesn't stall
        this.sendSignalOnOutput('Done');
        return;
      }
      // Custom seeded random number generator (Linear Congruential Generator)
      function SeededRandom(seed) {
        this.seed = seed % 2147483647;
        if (this.seed <= 0) this.seed += 2147483646;
      }

      SeededRandom.prototype.next = function () {
        this.seed = (this.seed * 16807) % 2147483647;
        return this.seed;
      };

      SeededRandom.prototype.nextFloat = function () {
        return (this.next() - 1) / 2147483646;
      };

      // Fisher-Yates shuffle algorithm using seeded random
      function shuffleArray(array, seededRandom) {
        const shuffled = [...array]; // Create a copy
        for (let i = shuffled.length - 1; i > 0; i--) {
          const j = Math.floor(seededRandom.nextFloat() * (i + 1));
          [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
        }
        return shuffled;
      }

      try {
        const symbolWeights = this._internal.symbolWeights;
        const randomSeeds = this._internal.randomSeeds;
        const columnSize = this._internal.columnSize;

        // A FAILED RUN MUST NOT LEAVE THE PREVIOUS RUN'S STRIPS STANDING (2026-08-16).
        //
        // The `finally` at the bottom sends Done on every path, INCLUDING these validation
        // returns — and that is deliberate: the canonical scaffold wires only Done out of this
        // node, and removing it re-opens the reels-don't-stop deadlock class. So Done stays.
        //
        // What was wrong is the state Done is sent OVER. The catch branch resets reelStrips to []
        // and flags it dirty; these two validation branches did neither. On a first run that is
        // harmless (reelStrips initialises to []), but on a RE-FIRE after a prior success they
        // left the earlier strips in place and announced Done over them — so downstream silently
        // recomputed on stale reels with nothing anywhere to indicate it. That is worse than the
        // empty case, because empty is a state every consumer already guards for
        // (weighted-reels.js checks it explicitly) and stale is undetectable.
        //
        // Making all three failure paths agree can only turn a stale read into an empty one.
        const failWith = (message, consoleMessage) => {
          console.warn(consoleMessage);
          this._internal.inspectData = { error: message };
          this._internal.reelStrips = [];
          this._internal.isComplete = false;
          this.flagOutputDirty('reelStrips');
          this.sendSignalOnOutput('Failure');
        };

        // Validate inputs — warn and signal Failure instead of throwing
        if (!Array.isArray(symbolWeights) || symbolWeights.length === 0) {
          failWith(
            'Symbol weights not available — ensure data is connected and flows before Do signal',
            'Reel Strips Generator: symbolWeights not yet available, skipping generation'
          );
          return;
        }

        if (!Array.isArray(randomSeeds) || randomSeeds.length < columnSize) {
          failWith(
            `Random seeds need ${columnSize} elements — ensure ISAAC array is connected before Do signal`,
            `Reel Strips Generator: randomSeeds needs at least ${columnSize} elements, got ${randomSeeds ? randomSeeds.length : 0}`
          );
          return;
        }

        // Check if all symbol weights are positive numbers
        if (!symbolWeights.every((weight) => typeof weight === 'number' && weight > 0)) {
          throw new Error('All symbol weights must be positive numbers');
        }

        // Generate base reel
        const baseReel = [];
        const minWeight = Math.min(...symbolWeights);
        const symbolWeightsRelativeToMin = symbolWeights.map((weight) => Math.ceil(weight / minWeight));

        for (let i = 1; i <= symbolWeights.length; i++) {
          baseReel.push(...Array(symbolWeightsRelativeToMin[i - 1]).fill(i));
        }

        // Generate reel strips using custom seeded random and shuffle
        const reelStrips = [];
        for (let i = 0; i < columnSize; i++) {
          const seededRandom = new SeededRandom(randomSeeds[i]);
          reelStrips.push(shuffleArray(baseReel, seededRandom));
        }

        // Store results
        this._internal.reelStrips = reelStrips;
        this._internal.isComplete = true;

        // Update inspect data
        this._internal.inspectData = {
          baseReel: baseReel,
          baseReelLength: baseReel.length,
          symbolWeights: symbolWeights,
          symbolWeightsRelativeToMin: symbolWeightsRelativeToMin,
          columnSize: columnSize,
          reelStrips: reelStrips,
          reelStripsCount: reelStrips.length
        };

        // Flag outputs as dirty
        this.flagOutputDirty('reelStrips');
      } catch (error) {
        console.error('Reel Strips Generator Error:', error.message);

        // Update inspect data with error
        this._internal.inspectData = {
          error: error.message
        };

        // Reset results
        this._internal.reelStrips = [];
        this._internal.isComplete = false;
        this.flagOutputDirty('reelStrips');
      } finally {
        // Always signal completion once the action has run, whether it
        // succeeded, validated-out (Failure also fired), or threw.
        this.sendSignalOnOutput('Done');
      }
    }
  }

