{
    calculateWinnings: function () {
      // Helper function to check payline
      function checkPayline(winningLine, betAmount, paytable, wildSymbol) {
        const symbols = winningLine[0];
        const comboLength = symbols.length;

        for (const symbol of symbols) {
          if (symbol !== wildSymbol) {
            if (paytable[symbol] && paytable[symbol][comboLength] !== undefined) {
              return Math.round(betAmount * paytable[symbol][comboLength]);
            }
            return 0;
          }
        }

        return 0;
      }

      try {
        const winningLines = this._internal.winningLines;
        const betAmount = this._internal.betAmount;
        const wildSymbol = this._internal.wildSymbol;
        const paytable = this._internal.paytable;

        // Validate inputs
        if (!Array.isArray(winningLines)) {
          throw new Error('Winning lines must be an array');
        }

        if (typeof betAmount !== 'number' || betAmount <= 0) {
          throw new Error('Bet amount must be a positive number');
        }

        if (typeof paytable !== 'object' || paytable === null) {
          throw new Error('Paytable must be an object');
        }

        let currentTotalWinnings = 0;
        const winningLinesDetails = [];

        for (const winLine of winningLines) {
          // Validate winLine structure
          if (!Array.isArray(winLine) || winLine.length !== 2) {
            console.warn('Invalid winning line structure, skipping:', winLine);
            continue;
          }

          if (!Array.isArray(winLine[0]) || !Array.isArray(winLine[1])) {
            console.warn('Invalid winning line symbols or positions structure, skipping:', winLine);
            continue;
          }

          const linePayout = checkPayline(winLine, betAmount, paytable, wildSymbol);
          currentTotalWinnings += linePayout;

          if (linePayout > 0) {
            winningLinesDetails.push({
              symbols: winLine[0],
              positions: winLine[1],
              payout: linePayout
            });
          }
        }

        // Sort winning lines details by payout descending
        winningLinesDetails.sort((a, b) => b.payout - a.payout);

        // Store results
        this._internal.spinWinnings = currentTotalWinnings;
        this._internal.winningLinesDetails = winningLinesDetails;

        // Update inspect data
        this._internal.inspectData = {
          winningLines: winningLines,
          betAmount: betAmount,
          wildSymbol: wildSymbol,
          paytable: paytable,
          spinWinnings: currentTotalWinnings,
          winningLinesCount: winningLines.length,
          winningDetailsCount: winningLinesDetails.length,
          winningLinesDetails: winningLinesDetails.slice(0, 5) // Show first 5 for inspection
        };

        // Flag outputs as dirty
        this.flagOutputDirty('spinWinnings');
        this.flagOutputDirty('winningLinesDetails');
      } catch (error) {
        console.error('Reel Ways Calculate Winnings Error:', error.message);

        // Update inspect data with error
        this._internal.inspectData = {
          error: error.message,
          inputs: {
            winningLines: this._internal.winningLines,
            betAmount: this._internal.betAmount,
            wildSymbol: this._internal.wildSymbol,
            paytable: this._internal.paytable
          }
        };

        // Reset results
        this._internal.spinWinnings = 0;
        this._internal.winningLinesDetails = [];
        this.flagOutputDirty('spinWinnings');
        this.flagOutputDirty('winningLinesDetails');
      } finally {
        // Send done signal
        this.sendSignalOnOutput('Done');
      }
    }
  }

helpers.code:
function checkPayline(winningLine, betAmount, paytable, wildSymbol) {
        const symbols = winningLine[0];
        const comboLength = symbols.length;

        for (const symbol of symbols) {
          if (symbol !== wildSymbol) {
            if (paytable[symbol] && paytable[symbol][comboLength] !== undefined) {
              return Math.round(betAmount * paytable[symbol][comboLength]);
            }
            return 0;
          }
        }

        return 0;
      }

