{
    checkWins: function () {
      // Helper function for cartesian product
      function cartesianProduct(arrays) {
        return arrays.reduce((a, b) => a.flatMap((d) => b.map((e) => [...d, e])), [[]]);
      }

      try {
        const numberOfSymbols = this._internal.numberOfSymbols;
        const wildSymbol = this._internal.wildSymbol;
        const freeSpinsSymbol = this._internal.freeSpinsSymbol;
        const reels = this._internal.reels;
        const minConsecutiveSymbols = this._internal.minConsecutiveSymbols;

        // Validate inputs
        if (!Array.isArray(reels) || reels.length === 0) {
          throw new Error('Reels array is required and cannot be empty');
        }

        if (!reels.every((reel) => Array.isArray(reel))) {
          throw new Error('All reels must be arrays');
        }

        const winningLines = [];

        let symbolSet = new Set(Array.from({ length: numberOfSymbols }, (_, i) => i + 1));
        const symbolSetList = [];
        symbolSet.delete(freeSpinsSymbol); // Exclude free spins symbol

        for (let i = 0; i < reels.length; i++) {
          const reel = reels[i];
          if (!reel.includes(wildSymbol)) {
            if (i >= minConsecutiveSymbols) {
              symbolSetList.push([new Set([...symbolSet].filter((x) => !reel.includes(x))), i]);
            }
            symbolSet = new Set([...symbolSet].filter((x) => reel.includes(x)));
          }
        }
        symbolSetList.push([symbolSet, reels.length]);

        for (const [symbols, comboLength] of symbolSetList) {
          for (const symbol of symbols) {
            const winningSymbols = [];
            const winningPositions = [];

            for (let i = 0; i < comboLength; i++) {
              const newSymbols = [];
              const newPositions = [];

              for (let j = 0; j < reels[i].length; j++) {
                if (reels[i][j] === symbol || reels[i][j] === wildSymbol) {
                  newSymbols.push(reels[i][j]);
                  newPositions.push([j, i]);
                }
              }

              winningSymbols.push(newSymbols);
              winningPositions.push(newPositions);
            }

            const symbolCombos = cartesianProduct(winningSymbols);
            const positionCombos = cartesianProduct(winningPositions);
            for (let k = 0; k < symbolCombos.length; k++) {
              winningLines.push([symbolCombos[k], positionCombos[k]]);
            }
          }
        }

        // Store results
        this._internal.winningLines = winningLines;

        // Update inspect data
        this._internal.inspectData = {
          numberOfSymbols: numberOfSymbols,
          wildSymbol: wildSymbol,
          freeSpinsSymbol: freeSpinsSymbol,
          reels: reels,
          minConsecutiveSymbols: minConsecutiveSymbols,
          winningLinesCount: winningLines.length,
          winningLines: winningLines.slice(0, 10) // Show first 10 for inspection
        };

        // Flag outputs as dirty
        this.flagOutputDirty('winningLines');
      } catch (error) {
        console.error('Reel Ways Check Wins Error:', error.message);

        // Update inspect data with error
        this._internal.inspectData = {
          error: error.message,
          inputs: {
            numberOfSymbols: this._internal.numberOfSymbols,
            wildSymbol: this._internal.wildSymbol,
            freeSpinsSymbol: this._internal.freeSpinsSymbol,
            reels: this._internal.reels,
            minConsecutiveSymbols: this._internal.minConsecutiveSymbols
          }
        };

        // Reset results
        this._internal.winningLines = [];
        this.flagOutputDirty('winningLines');
      } finally {
        // Send done signal
        this.sendSignalOnOutput('Done');
      }
    }
  }

