{
        scheduleRender: function () {
            if (!this._internal.hasScheduledRender) {
                this._internal.hasScheduledRender = true;
                this.scheduleAfterInputsHaveUpdated(this.doRender.bind(this));
            }
        },
        doRender: function () {
            this._internal.hasScheduledRender = false;

            try {
                const {
                    winningLinesDetails, paylines,
                    numCols, numRows,
                    gridWidth, gridHeight,
                    lineWidth, lineOpacity,
                    showAllPaylines, animateLines
                } = this._internal;

                const cellWidth = gridWidth / numCols;
                const cellHeight = gridHeight / numRows;
                const winningCells = [];
                let svgContent = '';

                // If showAllPaylines, render all payline definitions as dim background lines
                if (showAllPaylines && Array.isArray(paylines) && paylines.length > 0) {
                    for (let i = 0; i < paylines.length; i++) {
                        const line = paylines[i];
                        if (!Array.isArray(line)) continue;

                        const points = line.map(function (pos) {
                            if (!Array.isArray(pos) || pos.length < 2) return null;
                            // Payline definitions use [col, row] format
                            const col = pos[0];
                            const row = pos[1];
                            const x = (col * cellWidth) + (cellWidth / 2);
                            const y = (row * cellHeight) + (cellHeight / 2);
                            return x + ',' + y;
                        }).filter(Boolean).join(' ');

                        if (points) {
                            const color = PAYLINE_COLORS[i % PAYLINE_COLORS.length];
                            svgContent += '<polyline points="' + points + '" fill="none" stroke="' + color + '" stroke-width="1" stroke-dasharray="4,4" opacity="0.25"/>';
                        }
                    }
                }

                // Render winning lines
                if (Array.isArray(winningLinesDetails) && winningLinesDetails.length > 0) {
                    for (let idx = 0; idx < winningLinesDetails.length; idx++) {
                        var item = winningLinesDetails[idx];
                        if (!item || !Array.isArray(item.positions)) continue;

                        var lineNum = item.line || (idx + 1);
                        var color = PAYLINE_COLORS[(lineNum - 1) % PAYLINE_COLORS.length];

                        // Build polyline points from positions [row, col] (Calculate Winnings format)
                        var points = item.positions.map(function (pos) {
                            if (!Array.isArray(pos) || pos.length < 2) return null;
                            var row = pos[0];
                            var col = pos[1];
                            var x = (col * cellWidth) + (cellWidth / 2);
                            var y = (row * cellHeight) + (cellHeight / 2);
                            return x + ',' + y;
                        }).filter(Boolean).join(' ');

                        if (points) {
                            // Glow effect: wider semi-transparent line behind the main line
                            svgContent += '<polyline points="' + points + '" fill="none" stroke="' + color + '" stroke-width="' + (lineWidth + 4) + '" stroke-linecap="round" stroke-linejoin="round" opacity="' + (lineOpacity * 0.3) + '"'
                                + (animateLines ? ' class="payline-glow"' : '')
                                + '/>';
                            // Main line
                            svgContent += '<polyline points="' + points + '" fill="none" stroke="' + color + '" stroke-width="' + lineWidth + '" stroke-linecap="round" stroke-linejoin="round" opacity="' + lineOpacity + '"'
                                + (animateLines ? ' class="payline-main"' : '')
                                + '/>';

                            // Circle markers at each winning position
                            item.positions.forEach(function (pos) {
                                if (!Array.isArray(pos) || pos.length < 2) return;
                                var row = pos[0];
                                var col = pos[1];
                                var cx = (col * cellWidth) + (cellWidth / 2);
                                var cy = (row * cellHeight) + (cellHeight / 2);
                                svgContent += '<circle cx="' + cx + '" cy="' + cy + '" r="' + Math.max(4, lineWidth + 1) + '" fill="' + color + '" opacity="' + lineOpacity + '"/>';

                                // Track winning cells (1-based for UI compatibility)
                                winningCells.push({ col: col + 1, row: row + 1, line: lineNum });
                            });
                        }
                    }
                }

                // Build animation styles if enabled
                var animStyles = '';
                if (animateLines && svgContent) {
                    animStyles = '<style>'
                        + '@keyframes paylinePulse { 0%,100% { opacity: 1; } 50% { opacity: 0.5; } }'
                        + '.payline-main { animation: paylinePulse 1.5s ease-in-out infinite; }'
                        + '.payline-glow { animation: paylinePulse 1.5s ease-in-out infinite; }'
                        + '</style>';
                }

                // Build final SVG
                var svg = '';
                if (svgContent) {
                    svg = '<svg width="' + gridWidth + '" height="' + gridHeight
                        + '" viewBox="0 0 ' + gridWidth + ' ' + gridHeight
                        + '" xmlns="http://www.w3.org/2000/svg"'
                        + ' style="position:absolute;top:0;left:0;pointer-events:none;z-index:5">'
                        + animStyles + svgContent + '</svg>';
                }

                this.handleSuccess(svg, winningCells);
            } catch (error) {
                this.handleError(error.message);
            }
        },
        handleSuccess: function (svg, winningCells) {
            var totalWinLines = this._internal.winningLinesDetails
                ? this._internal.winningLinesDetails.length
                : 0;

            this._internal.paylineSVG = svg;
            this._internal.winningCells = winningCells;
            this._internal.totalWinLines = totalWinLines;
            this._internal.hasWin = totalWinLines > 0;

            this._internal.inspectData = {
                totalWinLines: totalWinLines,
                hasWin: totalWinLines > 0,
                winningCells: winningCells.length,
                svgLength: svg.length,
                gridDimensions: this._internal.gridWidth + 'x' + this._internal.gridHeight,
                grid: this._internal.numCols + 'x' + this._internal.numRows
            };

            this.flagOutputDirty('paylineSVG');
            this.flagOutputDirty('winningCells');
            this.flagOutputDirty('totalWinLines');
            this.flagOutputDirty('hasWin');

            this.sendSignalOnOutput('Done');
        },
        handleError: function (errorMessage) {
            console.error('Render Paylines Error:', errorMessage);

            this._internal.inspectData = {
                error: errorMessage,
                winningLinesDetails: this._internal.winningLinesDetails,
                numCols: this._internal.numCols,
                numRows: this._internal.numRows
            };

            this._internal.paylineSVG = '';
            this._internal.winningCells = [];
            this._internal.totalWinLines = 0;
            this._internal.hasWin = false;

            this.flagOutputDirty('paylineSVG');
            this.flagOutputDirty('winningCells');
            this.flagOutputDirty('totalWinLines');
            this.flagOutputDirty('hasWin');

            this.sendSignalOnOutput('Done');
        }
    }

