    weightFormula: {
      type: 'string',
      displayName: 'Weight Formula',
      group: 'Configuration',
      set: function (value) {
        // 2026-06-15 (trace 1781514456452): the old `value || DEFAULT` guard only
        // rejected FALSY input. A non-empty but MALFORMED formula ("10 - x" goes
        // negative, "sin(x)", a syntax error) passed straight through, then threw at
        // generation time (generateSymbolWeightsInternal → evaluateFormula).
        // handleGenerateReelStrips SWALLOWS that throw (console.error only), leaving
        // reelStrips empty, so handleSpin bails and runSingleSpin — the SOLE writer of
        // stopPosList — never runs: stopPositions stays [] forever and the reels spin
        // without ever landing (Done never fires). Probe the formula here (pure,
        // side-effect-free) and fall back to the known-valid default if it can't
        // produce valid weights, so generation can never throw on a bad formula.
        var candidate = value || DEFAULT_CONFIG.weightFormula;
        try {
          var probeCount = (this._internal && this._internal.config && this._internal.config.numberOfSymbols)
            || DEFAULT_CONFIG.numberOfSymbols;
          generateSymbolWeightsInternal(probeCount, candidate);
        } catch (err) {
          console.warn('[SlotMainEngine] weightFormula "' + candidate + '" is invalid (' +
            (err && err.message) + ') — falling back to default "' + DEFAULT_CONFIG.weightFormula +
