        const safeValue = clampNumber(value, DEFAULT_CONFIG.simulationRounds, 1, MAX_SIMULATION_ROUNDS);
        this.updateConfig('simulationRounds', safeValue);
      }
    },
    capital: {
      type: 'number',
      displayName: 'Capital',
      group: 'Bankroll',
      set: function (value) {
        const safeValue = Math.max(0, Number(value) || DEFAULT_CONFIG.capital);
        this.updateConfig('capital', safeValue);
        this._internal.state.capital = safeValue;
        this.flagOutputDirty('capitalFieldValue');
        this.flagOutputDirty('currentCapital');
      }
    },
    betAmount: {
      type: 'number',
      displayName: 'Bet Amount',
