        this.updateConfig('initialFreeSpins', safeValue);
        this._internal.state.currentFreeSpins = safeValue;
        this.flagOutputDirty('initialFreeSpinsFieldValue');
        this.flagOutputDirty('currentFreeSpins');
      }
    },
    enableCascading: {
