    lockReelStrips: {
      type: 'boolean',
      displayName: 'Lock Reel Strips',
      group: 'Control',
      default: false,
      set: function (value) {
        const lock = Boolean(value);
        const state = this._internal.state;
        if (lock && Array.isArray(state.reelStrips) && state.reelStrips.length > 0) {
          this._internal.flags.reelStripsLocked = true;
        } else if (!lock) {
          this._internal.flags.reelStripsLocked = false;
        }
        this.flagOutputDirty('isLocked');
      }
    },
    unlockReelStrips: {
      type: 'signal',
