prototypeExtensions.code:
{
    createDefaultState: function (capital, initialFreeSpins) {
      return {
        reelStrips: [],
        symbolWeights: [],
        reelStripsNonce: null,
        spinNonce: null,
        stopPosList: [],
        capital: capital,
        totalBets: 0,
        totalWinnings: 0,
        totalWinningsFromFreeSpins: 0,
        spinCount: 0,
        hits: 0,
        currentFreeSpins: initialFreeSpins,
        totalFreeSpinsWon: 0,
        currentFreeSpinsLines: [],
        currentFreeSpinsWon: 0,
        freeSpinsSymbolCount: 0,
        jackpotStartValue: capital > 0 ? capital * DEFAULT_CONFIG.jackpotBaseMultiplier : 0,
        jackpotAccumulator: 0,
        lastResult: null,
        debugReels: [],
        debugWinningLines: [],
        cascadeHistory: []
      };
    },
    createDefaultMetrics: function () {
      return {
        rtpSeries: [],
        hitFrequencySeries: [],
        spinWinningsSeries: [],
        stopPositionsHistory: [],
        spinNonceHistory: [],
        volatilityValues: [],
        volatility: { mean: 0, variance: 0, stdDev: 0, amplitude: 0 },
        symbolCounts: {},
        symbolFrequency: {}
      };
    },
    createDefaultAuditState: function () {
      return {
        autoEntries: [],
        manualEntries: [],
        replayEntries: [],
        replayIndex: -1
      };
    },
    scheduleLifecycleMount: function () {
      if (this._internal.flags.mounted) return;
      this._internal.flags.mounted = true;
      this.scheduleAfterInputsHaveUpdated(() => {
        this.handleMount();
      });
    },
    handleMount: function () {
      if (this._internal.flags.needsReelGeneration) {
        this.handleGenerateReelStrips(false);
      }
      this.updateAllOutputs();
    },
    updateConfig: function (key, value) {
      this._internal.config[key] = value;
      if (key === 'capital') {
        this._internal.state.capital = value;
      }
      if (key === 'initialFreeSpins') {
        this._internal.state.currentFreeSpins = value;
      }
      if (
        key === 'weightFormula' ||
        key === 'numberOfSymbols' ||
        key === 'columnSize' ||
        key === 'rowSize' ||
        key === 'freeSpinsSymbol' ||
        key === 'blockedReels'
      ) {
        this._internal.flags.needsReelGeneration = true;
      }
    },
    scheduleReelStripGeneration: function (resetState) {
      if (this._internal.flags.pendingGeneration) {
        this._internal.flags.forceResetOnGeneration = resetState;
        return;
      }
      this._internal.flags.pendingGeneration = true;
      this._internal.flags.forceResetOnGeneration = resetState;
      this.scheduleAfterInputsHaveUpdated(() => {
        const shouldReset = this._internal.flags.forceResetOnGeneration;
        this._internal.flags.pendingGeneration = false;
        this._internal.flags.forceResetOnGeneration = false;
        this.handleGenerateReelStrips(Boolean(shouldReset));
      });
    },
    scheduleSpin: function () {
      if (this._internal.flags.pendingSpin) return;
      this._internal.flags.pendingSpin = true;
      this.scheduleAfterInputsHaveUpdated(() => {
        this._internal.flags.pendingSpin = false;
        this.handleSpin();
      });
    },
    handleGenerateReelStrips: function (resetState) {
      // Guard: if locked, don't regenerate
      if (this._internal.flags.reelStripsLocked &&
        Array.isArray(this._internal.state.reelStrips) &&
        this._internal.state.reelStrips.length > 0) {
        return;
      }
      try {
        if (resetState) {
          this.resetStateForNewGeneration({ preserveSpinNonce: true });
        }
        const config = this._internal.config;
        const weights = generateSymbolWeightsInternal(config.numberOfSymbols, config.weightFormula);
        const seeds = generateSeeds(config.columnSize, this._internal.state.reelStripsNonce || Date.now());
        let strips = generateReelStripsFromWeights(weights, seeds, config.columnSize);
        if (config.enableFreeSpins) {
          strips = applyBlockedReels(strips, config.blockedReels, config.freeSpinsSymbol);
        }
        this._internal.state.symbolWeights = weights;
        this._internal.state.reelStrips = strips;
        this._internal.flags.needsReelGeneration = false;
        this.generateReelStripsSeed();
        this.updateAllOutputs();
      } catch (error) {
        console.error('SlotMainEngine - reel strips generation failed:', error);
      }
    },
    resetStateForNewGeneration: function (options = {}) {
      const preserveSpinNonce = Boolean(options.preserveSpinNonce);
      const previousSpinNonce = preserveSpinNonce ? this._internal.state.spinNonce : null;
      const config = this._internal.config;
      this._internal.state = this.createDefaultState(config.capital, config.initialFreeSpins);
      this._internal.metrics = this.createDefaultMetrics();
      this.resetJackpot();
      this._internal.audit = this.createDefaultAuditState();
      if (preserveSpinNonce && previousSpinNonce != null) {
        this._internal.state.spinNonce = previousSpinNonce;
      } else {
        this.generateSpinNonce();
      }
    },
    handleSpin: function () {
      if (this._internal.flags.needsReelGeneration) {
        this.handleGenerateReelStrips(false);
      }
      const config = this._internal.config;
      if (!Array.isArray(this._internal.state.reelStrips) || this._internal.state.reelStrips.length === 0) {
        return;
      }

      const iterations = config.enableSimulation
        ? clampNumber(config.simulationRounds, DEFAULT_CONFIG.simulationRounds, 1, MAX_SIMULATION_ROUNDS)
        : 1;

      const useReplay = config.enableReplay && this._internal.audit.replayEntries.length > 0;
      for (let i = 0; i < iterations; i++) {
        const replayPayload = useReplay ? this.getReplayPayload() : null;
        this.runSingleSpin(replayPayload);
        if (useReplay) {
          this.advanceReplayIndex();
        }
      }

      this.updateAllOutputs();

      // Emit Done signal after all data outputs are updated
      this._internal.flags.spinDone = true;
      this.flagOutputDirty('Done');
      // Reset Done flag on next tick so it acts as a pulse
      this.scheduleAfterInputsHaveUpdated(function () {
        this._internal.flags.spinDone = false;
      }.bind(this));
    },
    runSingleSpin: function (replayPayload) {
      const config = this._internal.config;
      const state = this._internal.state;

      if (replayPayload && replayPayload.reelStrips) {
        state.reelStrips = replayPayload.reelStrips;
      }

      const seeds = replayPayload?.seeds || generateSeeds(config.columnSize, this.generateSpinNonce());
      const stopPositions = replayPayload?.stopPosList || buildStopPositions(state.reelStrips, seeds);
      state.stopPosList = stopPositions;

      const reels = replayPayload?.reels || buildReels(state.reelStrips, stopPositions, config.rowSize);
      state.debugReels = reels;

      const evaluation = evaluateReelsAndWinnings({
        reels,
        config,
        symbolWeights: state.symbolWeights,
        betAmount: resolveBetAmount(config.betAmount, state.capital),
        enableCascading: config.enableCascading,
        cascadeLimit: config.cascadeLimit
      });

      const jackpotResult = checkJackpotWin(evaluation.finalReels, config.jackpotSymbol);

      const freeSpinState = config.enableFreeSpins
        ? calculateFreeSpinsStateInternal(evaluation.finalReels, {
          currentFreeSpins: state.currentFreeSpins,
          betAmount: config.betAmount,
          capital: state.capital,
          totalBets: state.totalBets,
          totalFreeSpinsWon: state.totalFreeSpinsWon,
          blockedReels: config.blockedReels,
          freeSpinsSymbol: config.freeSpinsSymbol
        })
        : null;

      const cascadeHits = evaluation.cascades.some((c) => c.spinWinnings > 0);
      const cascadingInProgress = config.enableCascading && cascadeHits;

      const betAmount = resolveBetAmount(config.betAmount, state.capital);
      if (!state.currentFreeSpins || state.currentFreeSpins <= 0) {
        state.capital -= betAmount;
        state.totalBets += betAmount;
      }

      let totalSpinWinnings = evaluation.totalSpinWinnings;

      if (jackpotResult.isWin) {
        totalSpinWinnings += state.jackpotAccumulator;
        state.jackpotAccumulator = state.jackpotStartValue;
      } else {
        state.jackpotAccumulator += betAmount * config.jackpotIncrementMultiplier;
      }

      state.capital += totalSpinWinnings;
      state.totalWinnings += totalSpinWinnings;
      if (state.currentFreeSpins > 0) {
        state.totalWinningsFromFreeSpins += totalSpinWinnings;
      }

      if (!cascadingInProgress) {
        state.spinCount += 1;
        if (totalSpinWinnings > 0) {
          state.hits += 1;
        }
      }

      if (freeSpinState) {
        // (capital/totalBets are owned solely by the bet+winnings accounting above; the
        // free-spin helper no longer returns them — see calculateFreeSpinsStateInternal.)
        state.currentFreeSpins = freeSpinState.currentFreeSpins;
        state.totalFreeSpinsWon = freeSpinState.totalFreeSpinsWon;
        state.currentFreeSpinsWon = freeSpinState.currentFreeSpinsWon;
        state.currentFreeSpinsLines = freeSpinState.currentFreeSpinsLines;
        state.freeSpinsSymbolCount = freeSpinState.freeSpinsSymbolCount;
      }

      state.debugWinningLines = evaluation.firstWinDetails;
      state.cascadeHistory = evaluation.cascades;

      this.updateSymbolFrequencies(evaluation.finalReels);
      this.updateMetrics(totalSpinWinnings);

      const finalResult = this.composeFinalResult({
        evaluation,
        jackpotResult,
        totalSpinWinnings,
        stopPositions,
        betAmount
      });
      state.lastResult = finalResult;

      this.captureAutoAuditEntry({
        reels,
        stopPosList: stopPositions,
        spinNonce: state.spinNonce,
        reelStrips: state.reelStrips,
        result: finalResult
      });
    },
    composeFinalResult: function ({ evaluation, jackpotResult, totalSpinWinnings, stopPositions, betAmount }) {
      const state = this._internal.state;
      const hitFrequency = getPercentage(state.hits, state.spinCount);
      const rtp = getPercentage(state.totalWinnings, state.totalBets);

      const result = {
        stopPosList: stopPositions,
        isBigWin: totalSpinWinnings > betAmount * 1000,
        totalBets: state.totalBets,
        totalWinnings: state.totalWinnings,
        hitFrequency: hitFrequency,
        RTP: rtp,
        currentFreeSpinsWon: state.currentFreeSpinsWon || 0,
        totalFreeSpinsWon: state.totalFreeSpinsWon || 0,
        currentFreeSpins: state.currentFreeSpins || 0,
        currentFreeSpinsLines: state.currentFreeSpinsLines || [],
        spinResults: {
          totalPayout: totalSpinWinnings,
          slotResults: transposeMatrix(evaluation.finalReels),
          winningLinesDetails: evaluation.firstWinDetails || [],
          cascades: evaluation.cascades,
          freeSpins: {
            awarded: state.currentFreeSpinsWon || 0,
            count: state.freeSpinsSymbolCount || 0,
            positions: (state.currentFreeSpinsLines || []).flatMap((line) => {
              return Array.isArray(line.positions) ? line.positions : [];
            }),
            symbols: (state.currentFreeSpinsLines || []).flatMap((line) => line.symbols || [])
          }
        }
      };

      if (jackpotResult.isWin) {
        result.spinResults.jackpotWinningDetails = {
          symbols: jackpotResult.symbols,
          positions: jackpotResult.positions,
          payout: state.jackpotAccumulator
        };
      }

      return result;
    },
    updateSymbolFrequencies: function (reels) {
      if (!Array.isArray(reels) || reels.length === 0) return;
      const counts = this._internal.metrics.symbolCounts;
      for (const column of reels) {
        if (!Array.isArray(column)) continue;
        for (const symbol of column) {
          if (typeof symbol !== 'number') continue;
          const key = String(symbol);
          counts[key] = (counts[key] || 0) + 1;
        }
      }

      const total = Object.values(counts).reduce((sum, val) => sum + (typeof val === 'number' ? val : 0), 0);
      const freq = {};
      if (total > 0) {
        Object.keys(counts).forEach((key) => {
          freq[key] = (counts[key] / total) * 100;
        });
      }
      this._internal.metrics.symbolFrequency = freq;
    },
    updateMetrics: function (payout) {
      const metrics = this._internal.metrics;
      const state = this._internal.state;

      const rtp = getPercentage(state.totalWinnings, state.totalBets);
      const hitFrequency = getPercentage(state.hits, state.spinCount);

      pushWithLimit(metrics.rtpSeries, rtp, SERIES_HISTORY_LIMIT);
      pushWithLimit(metrics.hitFrequencySeries, hitFrequency, SERIES_HISTORY_LIMIT);
      pushWithLimit(metrics.spinWinningsSeries, payout, SERIES_HISTORY_LIMIT);
      pushWithLimit(metrics.spinNonceHistory, state.spinNonce, SERIES_HISTORY_LIMIT);
      pushWithLimit(metrics.stopPositionsHistory, state.stopPosList, SERIES_HISTORY_LIMIT);

      pushWithLimit(metrics.volatilityValues, payout, VOLATILITY_HISTORY_LIMIT);
      metrics.volatility = computeVolatility(metrics.volatilityValues);
    },
    captureAutoAuditEntry: function ({ reels, stopPosList, spinNonce, reelStrips, result }) {
      const audit = this._internal.audit;
      audit.autoEntries.push({
        timestamp: new Date().toISOString(),
        reels,
        stopPosList,
        spinNonce,
        reelStrips,
        result
      });
      if (audit.autoEntries.length > 10000) {
        audit.autoEntries.shift();
      }
    },
    captureManualAuditEntry: function () {
      const state = this._internal.state;
      this._internal.audit.manualEntries.push({
        timestamp: new Date().toISOString(),
        reelStrips: deepClone(state.reelStrips),
        stopPosList: deepClone(state.stopPosList),
        spinNonce: state.spinNonce,
        result: state.lastResult
      });
    },
    exportAuditEntries: function () {
      const audit = this._internal.audit;
      const data = audit.manualEntries.length ? audit.manualEntries : audit.autoEntries;
      if (!data.length) return;
      downloadJsonFile('slot-audit-trail.json', data);
    },
    resetAuditEntries: function () {
      this._internal.audit = this.createDefaultAuditState();
    },
    openAuditImportDialog: function () {
      if (typeof document === 'undefined') {
        console.warn('Audit import is only available inside the editor.');
        return;
      }
      if (!this._internal.helpers.importInput) {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'application/json,.json';
        this._internal.helpers.importInput = input;
      }
      const inputEl = this._internal.helpers.importInput;
      inputEl.onchange = (event) => {
        const file = event.target.files && event.target.files[0];
        if (!file) {
          inputEl.value = '';
          return;
        }
        const reader = new FileReader();
        reader.onload = () => {
          try {
            const parsed = JSON.parse(reader.result || '[]');
            this.applyImportedAuditEntries(parsed);
          } catch (error) {
            console.error('Failed to parse audit trail file:', error);
          }
        };
        reader.readAsText(file);
        inputEl.value = '';
      };
      inputEl.click();
    },
    applyImportedAuditEntries: function (entries) {
      if (!Array.isArray(entries)) {
        console.warn('Invalid audit trail format.');
        return;
      }
      this._internal.audit.replayEntries = entries.map((entry) => normalizeReplayEntry(entry));
      this._internal.audit.replayIndex = 0;
    },
    getReplayPayload: function () {
      const audit = this._internal.audit;
      if (!audit.replayEntries.length) return null;
      const index = audit.replayIndex >= 0 ? audit.replayIndex : 0;
      return audit.replayEntries[index % audit.replayEntries.length];
    },
    advanceReplayIndex: function () {
      const audit = this._internal.audit;
      if (!audit.replayEntries.length) return;
      audit.replayIndex = (audit.replayIndex + 1) % audit.replayEntries.length;
    },
    moveToNextReplayEntry: function () {
      this.advanceReplayIndex();
    },
    exportMetrics: function () {
      const payload = {
        timestamp: new Date().toISOString(),
        config: this._internal.config,
        state: this._internal.state,
        metrics: {
          rtpSeries: this._internal.metrics.rtpSeries,
          hitFrequencySeries: this._internal.metrics.hitFrequencySeries,
          spinWinningsSeries: this._internal.metrics.spinWinningsSeries,
          volatility: this._internal.metrics.volatility
        }
      };
      downloadJsonFile('slot-metrics.json', payload);
    },
    generateReelStripsSeed: function () {
      this._internal.state.reelStripsNonce = randomLargeInt();
      this.flagOutputDirty('reelStripsNonce');
    },
    generateSpinNonce: function () {
      this._internal.state.spinNonce = randomLargeInt();
      this.flagOutputDirty('spinNonce');
      return this._internal.state.spinNonce;
    },
    resetJackpot: function () {
      const config = this._internal.config;
      const base = resolveBetAmount(config.betAmount, config.capital) * config.jackpotBaseMultiplier;
      this._internal.state.jackpotStartValue = base;
      this._internal.state.jackpotAccumulator = base;
      this.flagOutputDirty('jackpotStartValue');
      this.flagOutputDirty('jackpotAccumulatedValue');
    },
    updateAllOutputs: function () {
      const outputs = [
        'reelStrips',
        'stopPosList',
        'currentCapital',
        'currentFreeSpins',
        'jackpotStartValue',
        'jackpotAccumulatedValue',
        'reelStripsNonce',
        'spinNonce',
        'rtpSeries',
        'hitFrequencySeries',
        'spinWinningsSeries',
        'finalResult',
        'volatilityMean',
        'volatilityStdDev',
        'volatilityVariance',
        'volatilityAmplitude',
        'capitalFieldValue',
        'initialFreeSpinsFieldValue',
        'debugReels',
        'debugWinningLines'
      ];
      outputs.forEach((name) => this.flagOutputDirty(name));
    }
  }

helpers.code:
function clampNumber(value, fallback, min, max) {
  const num = Number(value);
  if (Number.isNaN(num)) return fallback;
  return Math.max(min, Math.min(max, num));
}

function pushWithLimit(array, value, limit) {
  if (!Array.isArray(array)) return;
  array.push(value);
  if (array.length > limit) {
    array.shift();
  }
}

function randomLargeInt() {
  return Math.floor(Math.random() * 1e15);
}

function deepClone(obj) {
  return JSON.parse(JSON.stringify(obj));
}

function getPercentage(value, total) {
  if (!total || !Number.isFinite(total) || total === 0) return 0;
  return (value / total) * 100;
}

function formatNumber(v) {
  if (!Number.isFinite(v)) return 0;
  return Math.round(v * 100) / 100;
}

function createSeededRandom(seed) {
  let currentSeed = Math.floor(Math.abs(Number(seed) || Date.now()));
  if (!currentSeed || currentSeed <= 0) currentSeed = RNG_MULTIPLIER;
  return {
    next() {
      currentSeed = (currentSeed * RNG_MULTIPLIER) % RNG_MODULUS;
      return currentSeed;
    },
    nextFloat() {
      return (this.next() - 1) / (RNG_MODULUS - 1);
    },
    integer(min, max) {
      return Math.floor(this.nextFloat() * (max - min + 1)) + min;
    }
  };
}

function generateSeeds(columnSize, baseSeed) {
  const seeds = [];
  const seededRandom = createSeededRandom(baseSeed);
  for (let i = 0; i < columnSize; i++) {
    seeds.push(seededRandom.next());
  }
  return seeds;
}

function generateSymbolWeightsInternal(numberOfSymbols, weightFormula) {
  const weights = [];
  for (let idx = 1; idx <= numberOfSymbols; idx++) {
    const value = evaluateFormula(weightFormula, idx);
    if (!Number.isFinite(value) || value <= 0) {
      throw new Error('Invalid symbol weight for x=' + idx);
    }
    weights.push(value);
  }
  const total = weights.reduce((sum, val) => sum + val, 0);
  return weights.map((w) => (w / total) * 100);
}

function evaluateFormula(formula, x) {
  try {
    const scope = { x, pi: Math.PI, e: Math.E };
    let processed = String(formula || 'x')
      .replace(/\bsin\b/g, 'Math.sin')
      .replace(/\bcos\b/g, 'Math.cos')
      .replace(/\btan\b/g, 'Math.tan')
      .replace(/\blog\b/g, 'Math.log')
      .replace(/\bexp\b/g, 'Math.exp')
      .replace(/\bsqrt\b/g, 'Math.sqrt')
      .replace(/\bpow\b/g, 'Math.pow')
      .replace(/\babs\b/g, 'Math.abs')
      .replace(/\bfloor\b/g, 'Math.floor')
      .replace(/\bceil\b/g, 'Math.ceil')
      .replace(/\bround\b/g, 'Math.round');
    Object.keys(scope).forEach((key) => {
      const regex = new RegExp('\\b' + key + '\\b', 'g');
      processed = processed.replace(regex, scope[key]);
    });
    const value = eval(processed); // eslint-disable-line no-eval
    if (typeof value !== 'number' || Number.isNaN(value)) {
      throw new Error('Formula must evaluate to a number');
    }
    return value;
  } catch (error) {
    throw new Error('Formula evaluation error: ' + error.message);
  }
}

function generateReelStripsFromWeights(weights, seeds, columnSize) {
  if (!Array.isArray(weights) || !weights.length) {
    throw new Error('Symbol weights not provided');
  }
  const minWeight = Math.min(...weights);
  const relativeWeights = weights.map((weight) => Math.ceil(weight / minWeight));
  const baseReel = [];
  for (let symbol = 1; symbol <= weights.length; symbol++) {
    baseReel.push(...Array(relativeWeights[symbol - 1]).fill(symbol));
  }
  const strips = [];
  for (let column = 0; column < columnSize; column++) {
    const seeded = createSeededRandom(seeds[column] || Date.now() + column);
    const working = baseReel.slice();
    for (let i = working.length - 1; i > 0; i--) {
      const j = Math.floor(seeded.nextFloat() * (i + 1));
      [working[i], working[j]] = [working[j], working[i]];
    }
    strips.push(working);
  }
  return strips;
}

function applyBlockedReels(reelStrips, blockedReels, freeSpinsSymbol) {
  if (!Array.isArray(reelStrips)) return reelStrips;
  const blockedIndices = parseBlockedReels(blockedReels);
  const result = reelStrips.map((reel) => reel.slice());
  for (const idx of blockedIndices) {
    if (idx < 0 || idx >= result.length) continue;
    const reel = result[idx];
    const fsIndex = reel.indexOf(freeSpinsSymbol);
    if (fsIndex !== -1) {
      reel[fsIndex] = 1;
    }
  }
  return result;
}

function parseBlockedReels(blockedReels) {
  if (!blockedReels) return [];
  return blockedReels
    .split(',')
    .map((value) => Number(value.trim()))
    .filter((value) => Number.isInteger(value));
}

function buildStopPositions(reelStrips, seeds) {
  const stopPositions = [];
  for (let column = 0; column < reelStrips.length; column++) {
    const strip = reelStrips[column];
    const seeded = createSeededRandom(seeds[column] || Date.now() + column);
    stopPositions.push(seeded.integer(0, strip.length - 1));
  }
  return stopPositions;
}

function buildReels(reelStrips, stopPositions, rowSize) {
  const reels = [];
  for (let column = 0; column < reelStrips.length; column++) {
    const strip = reelStrips[column];
    const pointer = stopPositions[column] || 0;
    const columnSymbols = [];
    for (let row = 0; row < rowSize; row++) {
      columnSymbols.push(strip[(pointer + row) % strip.length]);
    }
    reels.push(columnSymbols);
  }
  return reels;
}

function transposeMatrix(columns) {
  if (!Array.isArray(columns) || !columns.length) return [];
  const rows = columns[0].length || 0;
  const transposed = [];
  for (let row = 0; row < rows; row++) {
    const rowValues = [];
    for (let col = 0; col < columns.length; col++) {
      rowValues.push(columns[col][row]);
    }
    transposed.push(rowValues);
  }
  return transposed;
}

function evaluateStandardReels(reels, config, betAmount) {
  const paylinesResult = checkWins(reels, config);
  const winningsResult = calculateWinnings(
    paylinesResult.winningLines,
    betAmount,
    config.wildSymbol,
    buildPaytable(config),
    paylinesResult.paylines
  );
  return {
    total: winningsResult.total,
    details: winningsResult.details
  };
}

function evaluateReelWays(reels, config, betAmount) {
  const winningLines = checkReelWaysWins(reels, config);
  const winnings = calculateReelWaysWinnings(winningLines, betAmount, config.wildSymbol, buildPaytable(config));
  return {
    total: winnings.total,
    details: winnings.details
  };
}

function checkWins(reels, config) {
  if (!Array.isArray(reels) || !reels.length) {
    return { winningLines: [], paylines: [] };
  }
  const winningLines = [];
  const paylines = buildDefaultPaylines(reels);
  const { wildSymbol, freeSpinsSymbol, minConsecutiveSymbols } = config;

  for (const [index, line] of paylines.entries()) {
    const lineSymbols = [];
    for (const [col, row] of line) {
      const symbol = reels[col][row];
      lineSymbols.push(symbol);
    }

    if (lineSymbols.every((symbol) => symbol === wildSymbol || symbol === freeSpinsSymbol)) {
      continue;
    }

    let firstNonWild = null;
    let valid = true;
    let longest = [];

    for (let i = 0; i < lineSymbols.length; i++) {
      const symbol = lineSymbols[i];
      if (symbol !== wildSymbol) {
        if (firstNonWild === null) {
          firstNonWild = symbol;
        } else if (symbol !== firstNonWild) {
          valid = false;
          break;
        }
      }
      if (valid && i + 1 >= minConsecutiveSymbols) {
        longest = lineSymbols.slice(0, i + 1);
      }
    }

    if (valid && longest.length) {
      winningLines.push([index + 1, longest]);
    }
  }

  return { winningLines, paylines };
}

function calculateWinnings(winningLines, betAmount, wildSymbol, paytable, paylines) {
  let total = 0;
  const details = [];
  const lineCount = winningLines.length || 1;
  const betPerLine = betAmount / lineCount;

  for (const winLine of winningLines) {
    const lineIndex = winLine[0] - 1;
    const symbols = winLine[1];
    const combination = symbols.length;
    let payoutSymbol = symbols.find((symbol) => symbol !== wildSymbol) || symbols[0];
    const payout = paytable[payoutSymbol] && paytable[payoutSymbol][combination];
    if (payout) {
      const amount = Math.round(betPerLine * payout);
      total += amount;
      const positions =
        Array.isArray(paylines) && paylines[lineIndex] ? paylines[lineIndex].slice(0, symbols.length) : [];
      details.push({ symbols, payout: amount, positions });
    }
  }

  return { total, details };
}

function checkReelWaysWins(reels, config) {
  if (!Array.isArray(reels) || !reels.length) return [];
  const { wildSymbol, freeSpinsSymbol, minConsecutiveSymbols } = config;
  const numberOfSymbols = config.numberOfSymbols;
  const winningLines = [];

  let symbolSet = new Set(Array.from({ length: numberOfSymbols }, (_, idx) => idx + 1));
  const symbolSetList = [];
  symbolSet.delete(freeSpinsSymbol);

  for (let col = 0; col < reels.length; col++) {
    const reel = reels[col];
    if (!reel.includes(wildSymbol)) {
      if (col >= minConsecutiveSymbols) {
        symbolSetList.push([new Set([...symbolSet].filter((value) => !reel.includes(value))), col]);
      }
      symbolSet = new Set([...symbolSet].filter((value) => reel.includes(value)));
    }
  }
  symbolSetList.push([symbolSet, reels.length]);

  for (const [symbols] of symbolSetList) {
    for (const symbol of symbols) {
      winningLines.push([[symbol], symbol]);
    }
  }

  return winningLines;
}

function calculateReelWaysWinnings(winningLines, betAmount, wildSymbol, paytable) {
  let total = 0;
  const details = [];
  for (const winLine of winningLines) {
    const symbols = winLine[0];
    const combination = symbols.length;
    let payoutSymbol = symbols.find((symbol) => symbol !== wildSymbol) || symbols[0];
    const payout = paytable[payoutSymbol] && paytable[payoutSymbol][combination];
    if (payout) {
      const amount = Math.round(betAmount * payout);
      total += amount;
      details.push({ symbols, payout: amount });
    }
  }
  return { total, details };
}

function cascadeReelsInternal(reels, winningLinesDetails, symbolWeights) {
  const columns = reels.length;
  const rows = reels[0].length;
  const positionsToClear = new Set();
  for (const detail of winningLinesDetails || []) {
    const positions = detail.positions || [];
    for (const pos of positions) {
      const row = Number(Array.isArray(pos) ? pos[0] : pos?.row);
      const col = Number(Array.isArray(pos) ? pos[1] : pos?.col);
      if (Number.isInteger(row) && Number.isInteger(col) && col >= 0 && row >= 0 && col < columns && row < rows) {
        positionsToClear.add(col + ':' + row);
      }
    }
  }

  const baseReel = buildCascadeBase(symbolWeights);
  const nextReels = [];
  for (let col = 0; col < columns; col++) {
    const kept = [];
    for (let row = 0; row < rows; row++) {
      const key = col + ':' + row;
      if (!positionsToClear.has(key)) {
        kept.push(reels[col][row]);
      }
    }
    const empties = rows - kept.length;
    const replacements = [];
    for (let i = 0; i < empties; i++) {
      replacements.push(pickRandomFrom(baseReel));
    }
    nextReels.push(replacements.concat(kept));
  }
  return nextReels;
}

function buildCascadeBase(symbolWeights) {
  if (!Array.isArray(symbolWeights) || !symbolWeights.length) {
    return [1, 2, 3, 4, 5, 6, 7];
  }
  const minWeight = Math.min(...symbolWeights);
  const relative = symbolWeights.map((w) => Math.max(1, Math.ceil(w / minWeight)));
  const base = [];
  for (let symbol = 1; symbol <= symbolWeights.length; symbol++) {
    base.push(...Array(relative[symbol - 1]).fill(symbol));
  }
  return base;
}

function pickRandomFrom(array) {
  return array[Math.floor(Math.random() * array.length)];
}

function calculateFreeSpinsStateInternal(reels, state) {
  const blockedReels = parseBlockedReels(state.blockedReels);
  let currentFreeSpins = state.currentFreeSpins || 0;
  let totalFreeSpinsWon = state.totalFreeSpinsWon || 0;

  // This helper owns ONLY the free-spin counters. Bet deduction and winnings are applied by
  // runSingleSpin, which already skips charging a bet during a free spin — so this must NOT
  // touch capital/totalBets. Previously it refunded a bet that was never charged AND its
  // snapshot was written back over the just-computed capital/totalBets (every spin, since
  // free spins are on by default), discarding the bet + winnings and corrupting balance + RTP.
  if (currentFreeSpins > 0) {
    currentFreeSpins--;
  }

  let freeSpinsSymbolCount = 0;
  const currentFreeSpinsLines = [];
  for (let reelIdx = 0; reelIdx < reels.length; reelIdx++) {
    if (blockedReels.includes(reelIdx)) continue;
    const reel = reels[reelIdx];
    for (let rowIdx = 0; rowIdx < reel.length; rowIdx++) {
      const symbol = reel[rowIdx];
      if (symbol === state.freeSpinsSymbol) {
        freeSpinsSymbolCount++;
        currentFreeSpinsLines.push({
          symbols: [symbol],
          positions: [[rowIdx, reelIdx]]
        });
        break;
      }
    }
  }

  let currentFreeSpinsWon = 0;
  if (freeSpinsSymbolCount >= 2) {
    currentFreeSpinsWon = (freeSpinsSymbolCount * (freeSpinsSymbolCount + 1)) / 2;
  }
  totalFreeSpinsWon += currentFreeSpinsWon;
  currentFreeSpins += currentFreeSpinsWon;

  return {
    currentFreeSpins,
    freeSpinsSymbolCount,
    currentFreeSpinsWon,
    totalFreeSpinsWon,
    currentFreeSpinsLines
  };
}

function checkJackpotWin(reels, winningSymbol) {
  if (!Array.isArray(reels) || !reels.length) return { isWin: false, positions: [], symbols: [] };
  const positions = [];
  let columnsWithSymbol = 0;
  for (let col = 0; col < reels.length; col++) {
    let hasSymbol = false;
    const column = reels[col];
    for (let row = 0; row < column.length; row++) {
      if (column[row] === winningSymbol) {
        positions.push([row, col]);
        hasSymbol = true;
      }
    }
    if (hasSymbol) columnsWithSymbol += 1;
  }
  return {
    isWin: columnsWithSymbol === reels.length && reels.length > 0,
    positions,
    symbols: Array(reels.length).fill(winningSymbol)
  };
}

function computeVolatility(values) {
  const n = values.length;
  if (!n) {
    return { mean: 0, variance: 0, stdDev: 0, amplitude: 0 };
  }
  const mean = values.reduce((sum, val) => sum + val, 0) / n;
  let variance = 0;
  if (n > 1) {
    const diffs = values.map((val) => (val - mean) ** 2);
    variance = diffs.reduce((sum, val) => sum + val, 0) / (n - 1);
  }
  const stdDev = Math.sqrt(variance);
  const minVal = Math.min(...values);
  const maxVal = Math.max(...values);
  const amplitude = mean !== 0 ? (maxVal - minVal) / Math.abs(mean) : maxVal - minVal;
  return {
    mean,
    variance,
    stdDev,
    amplitude
  };
}

function resolveBetAmount(betAmount, capital) {
  if (!capital && capital !== 0) return betAmount;
  return Math.min(betAmount, capital);
}

function buildPaytable(config) {
  const paytable = {};
  for (let symbol = 1; symbol <= config.numberOfSymbols; symbol++) {
    paytable[symbol] = {};
    for (let count = config.minConsecutiveSymbols; count <= config.columnSize; count++) {
      paytable[symbol][count] = evaluateFormula(config.payoutFormula, symbol) * count;
    }
  }
  return paytable;
}

function normalizeReplayEntry(entry) {
  if (!entry || typeof entry !== 'object') {
    return {};
  }
  return {
    reelStrips: deepClone(entry['Reel Strips'] || entry.reelStrips || []),
    stopPosList: deepClone(entry['Stop Positions List'] || entry.stopPosList || []),
    seeds: entry.seeds || null,
    reels: entry.reels || null
  };
}

function downloadJsonFile(filename, data) {
  if (typeof document === 'undefined') {
    console.warn('File downloads are only available when running inside the editor.');
    return;
  }
  try {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  } catch (error) {
    console.error('Failed to export file:', error);
  }
}

