        this._internal.hasScheduledCalculation = true;
        this.scheduleAfterInputsHaveUpdated(this.doCalculation.bind(this));
      }
    },
    doCalculation: function () {
      this._internal.hasScheduledCalculation = false;

      try {
      // Get input values
      let capital = this._internal.capital;
      let totalBets = this._internal.totalBets;
      let spinWinnings = this._internal.spinWinnings;
      let totalWinnings = this._internal.totalWinnings;
      let currentFreeSpins = this._internal.currentFreeSpins;
      let totalWinningsFromFreeSpins = this._internal.totalWinningsFromFreeSpins;
      let spinCount = this._internal.spinCount;
      let hits = this._internal.hits;
      const jackpotWinnings = this._internal.jackpotWinnings;
      const winningJackpot = this._internal.winningJackpot;
      const cascadingReelsEnabled = Boolean(this._internal.cascadingReelsEnabled);

      // Determine if cascading is in progress.
      //
      // (2026-09-04, export 1788429855009) This one line decides whether the player pays for
      // the spin. It only means "mid-cascade payout" when `spinWinnings` is the win of THIS
      // pass; fed an accumulated chain total it reads as true at settle on every winning
      // spin, and the bet below is never deducted. See the node description for the full
      // contract, and verify_logic_correctness CHECK 31 for the audit that now refuses that
      // wiring. Behaviour deliberately unchanged — live games depend on these semantics.
      const isCascadingInProgress = cascadingReelsEnabled && spinWinnings > 0;

      // Perform bet and spin counters only when not cascading in progress
      if (!isCascadingInProgress && currentFreeSpins === 0) {
        capital -= this._internal.betAmount;
        totalBets += this._internal.betAmount;
      }

      if (spinWinnings > 0) {
        capital += spinWinnings;
        if (!isCascadingInProgress) {
          hits++;
        }
        totalWinnings += spinWinnings;

        if (currentFreeSpins > 0) {
          totalWinningsFromFreeSpins += spinWinnings;
        }
      }

      // Apply jackpot winnings if flagged
      if (winningJackpot && jackpotWinnings > 0) {
        capital += jackpotWinnings;
        totalWinnings += jackpotWinnings;
      }
      if (!isCascadingInProgress) {
        spinCount++;
      }

      // Store results
      this._internal.resultCapital = capital;
      this._internal.resultTotalBets = totalBets;
      this._internal.resultTotalWinnings = totalWinnings;
      this._internal.resultTotalWinningsFromFreeSpins = totalWinningsFromFreeSpins;
      this._internal.resultSpinCount = spinCount;
      this._internal.resultHits = hits;

      // Update inspect data
      this._internal.inspectData = {
        betAmount: this._internal.betAmount,
        inputCapital: this._internal.capital,
        resultCapital: capital,
        inputTotalBets: this._internal.totalBets,
        resultTotalBets: totalBets,
        spinWinnings: spinWinnings,
        inputSpinCount: this._internal.spinCount,
        resultSpinCount: spinCount,
        hits: hits
      };

      // Flag outputs as dirty
      this.flagOutputDirty('capital');
      this.flagOutputDirty('totalBets');
      this.flagOutputDirty('totalWinnings');
      this.flagOutputDirty('totalWinningsFromFreeSpins');
      this.flagOutputDirty('spinCount');
      this.flagOutputDirty('hits');
      } finally {
        // Send Done signal
        this.sendSignalOnOutput('Done');
      }
    }
  }

