{
    scheduleCalculation: function () {
      if (!this._internal.hasScheduledCalculation) {
        this._internal.hasScheduledCalculation = true;
        this.scheduleAfterInputsHaveUpdated(this.doCalculation.bind(this));
      }
    },
    doCalculation: function () {
      this._internal.hasScheduledCalculation = false;

      try {
        // Get input values
        const reels = this._internal.reels;
        const stopPosList = this._internal.stopPosList;
        const spinWinnings = this._internal.spinWinnings;
        const betAmount = this._internal.betAmount;
        const totalBets = this._internal.totalBets;
        const totalWinnings = this._internal.totalWinnings;
        const hits = this._internal.hits;
        const spinCount = this._internal.spinCount;
        const currentFreeSpinsWon = this._internal.currentFreeSpinsWon;
        const totalFreeSpinsWon = this._internal.totalFreeSpinsWon;
        const currentFreeSpins = this._internal.currentFreeSpins;
        const currentFreeSpinsLines = this._internal.currentFreeSpinsLines;
        const winningLinesDetails = this._internal.winningLinesDetails;
        const freeSpinsSymbolCount = this._internal.freeSpinsSymbolCount || 0;
        const jackpotWinnings = Number(this._internal.jackpotWinnings) || 0;
        const winningJackpot = Boolean(this._internal.winningJackpot);
        const jackpotWinningPositions = Array.isArray(this._internal.jackpotWinningPositions)
          ? this._internal.jackpotWinningPositions
          : [];

        // Process slot results
        const slotResults = reels.length > 0 && reels[0] ? reels[0].map((_, i) => reels.map((col) => col[i])) : [];

        // Create final result object
        let finalResult = {
          stopPosList: stopPosList,
          isBigWin: spinWinnings > betAmount * 1000,
          totalBets: totalBets,
          totalWinnings: totalWinnings,
          hitFrequency: spinCount > 0 ? (hits / spinCount) * 100 : 0,
          RTP: totalBets > 0 ? (totalWinnings / totalBets) * 100 : 0,
          currentFreeSpinsWon: currentFreeSpinsWon || 0,
          totalFreeSpinsWon: totalFreeSpinsWon || 0,
          currentFreeSpins: currentFreeSpins || 0,
          currentFreeSpinsLines: currentFreeSpinsLines || []
        };

        // If simulation is enabled, push into series arrays
        if (this._internal.enableSimulation) {
          if (Array.isArray(this._internal.hitFrequencyDataSeries)) {
            this._internal.hitFrequencyDataSeries.push(finalResult.hitFrequency);
          }
          if (Array.isArray(this._internal.RTPDataSeries)) {
            this._internal.RTPDataSeries.push(finalResult.RTP);
          }
        }

        // Process free spins symbols and positions
        const symbols = [];
        const positions = [];
        let posCount = 0;

        for (const line of finalResult.currentFreeSpinsLines) {
          posCount++;
          if (line.symbols && line.symbols.length > 0) {
            symbols.push(line.symbols[0]);
          }
          if (line.positions && line.positions.length > 0) {
            positions.push([line.positions[0], posCount - 1]);
          }
        }

        // Add spin results
        const spinResults = {
          totalPayout: spinWinnings + (winningJackpot ? jackpotWinnings : 0),
          slotResults: slotResults,
          winningLinesDetails: JSON.parse(JSON.stringify(winningLinesDetails || [])), // Deep clone equivalent
          freeSpins: {
            awarded: currentFreeSpinsWon,
            count: freeSpinsSymbolCount,
            positions: positions,
            symbols: symbols
          }
        };

        if (winningJackpot) {
          // Derive winning symbol from the first jackpot position and reels
          let jackpotSymbol = null;
          if (Array.isArray(reels) && reels.length && jackpotWinningPositions.length) {
            const [row, col] = jackpotWinningPositions[0];
            if (
              Number.isInteger(col) &&
              Number.isInteger(row) &&
              col >= 0 &&
              col < reels.length &&
              Array.isArray(reels[col]) &&
              row >= 0 &&
              row < reels[col].length
            ) {
              jackpotSymbol = reels[col][row];
            }
          }

          const symbolsJackpot = jackpotSymbol != null ? Array(reels.length).fill(jackpotSymbol) : [];

          spinResults.jackpotWinningDetails = {
            symbols: symbolsJackpot,
            positions: jackpotWinningPositions,
            payout: jackpotWinnings
          };
        }

        finalResult.spinResults = spinResults;

        // Store result
        this._internal.finalResult = finalResult;

        // Update inspect data
        this._internal.inspectData = {
          reelsCount: reels.length,
          spinWinnings: spinWinnings,
          isBigWin: finalResult.isBigWin,
          hitFrequency: finalResult.hitFrequency,
          RTP: finalResult.RTP,
          freeSpinsAwarded: currentFreeSpinsWon,
          slotResultsRows: slotResults.length
        };

        // Flag outputs dirty
        this.flagOutputDirty('finalResult');
        this.flagOutputDirty('stopPosList');
        this.flagOutputDirty('isBigWin');
        this.flagOutputDirty('totalBets');
        this.flagOutputDirty('totalWinnings');
        this.flagOutputDirty('hitFrequency');
        this.flagOutputDirty('RTP');
        this.flagOutputDirty('currentFreeSpinsWon');
        this.flagOutputDirty('totalFreeSpinsWon');
        this.flagOutputDirty('currentFreeSpins');
        this.flagOutputDirty('currentFreeSpinsLines');
        this.flagOutputDirty('spinResults');
        this.flagOutputDirty('hitFrequencyDataSeries');
        this.flagOutputDirty('RTPDataSeries');
      } finally {
        // Send Done signal
        this.sendSignalOnOutput('Done');
      }
    }
  }

