        this.scheduleAfterInputsHaveUpdated(this.doCompute.bind(this));
      }
    },
    doCompute: function () {
      this._internal.hasScheduledCompute = false;

      try {
        const numSymbols = this._internal.numberOfSymbols;
        const reels = this._internal.reels;

        // Validate reels structure: array of arrays of numbers
        if (!Array.isArray(reels)) {
          throw new Error('Reels must be an array.');
        }
        const allRows = [];
        for (let i = 0; i < reels.length; i++) {
          const reel = reels[i];
          if (!Array.isArray(reel)) {
            throw new Error(`Reel at index ${i} must be an array.`);
          }
          for (let j = 0; j < reel.length; j++) {
            const sym = reel[j];
            if (typeof sym !== 'number') continue;
            allRows.push(sym);
          }
        }

        // Initialize counts from retained state with 0 to keep keys stable
        const counts = { ...this._internal.symbolCountResults };
        for (let s = 1; s <= numSymbols; s++) {
          const key = String(s);
          if (typeof counts[key] !== 'number') counts[key] = 0;
        }

        // Count symbols within 1..numSymbols
        for (let k = 0; k < allRows.length; k++) {
          const value = allRows[k];
          if (value >= 1 && value <= numSymbols) {
            const key = String(value);
            counts[key] = (counts[key] || 0) + 1;
          }
        }

        // Inspect data (also provide totals and percentages for debugging)
        const totalCount = Object.values(counts).reduce((a, b) => a + (typeof b === 'number' ? b : 0), 0);
        const percentages = {};
        if (totalCount > 0) {
          for (let s = 1; s <= numSymbols; s++) {
            const key = String(s);
            const count = counts[key] || 0;
            percentages[key] = (count / totalCount) * 100;
          }
        }

        // Update state
        this._internal.symbolCountResults = counts;
        this._internal.symbolFrequencyResults = percentages;

        this._internal.inspectData = {
          numberOfSymbols: numSymbols,
          reelsInput: reels,
          counts: counts,
          totalCount: totalCount,
          percentages: percentages
        };

        // Flag result outputs and send Done
        this.flagOutputDirty('symbolCountResults');
        this.flagOutputDirty('symbolFrequencyResults');
      } catch (error) {
        console.error('Symbol Frequency Tracker Error:', error.message);
        this._internal.inspectData = {
          error: error.message,
          numberOfSymbols: this._internal.numberOfSymbols
        };
      } finally {
        this.sendSignalOnOutput('Done');
      }
    }
  }

