{
    scheduleCalculation: function () {
      if (!this._internal.hasScheduledCalculation) {
        this._internal.hasScheduledCalculation = true;
        this.scheduleAfterInputsHaveUpdated(this.doCalculation.bind(this));
      }
    },
    doCalculation: function () {
      this._internal.hasScheduledCalculation = false;

      try {
      const spinResults = this._internal.spinResults || {};
      // Expecting an object similar to Spin Result node's output
      // spinResults.totalPayout: number
      // spinResults.slotResults: matrix (unused here)
      // spinResults.winningLinesDetails: array (unused)
      // spinResults.freeSpins: object (unused)

      // Determine the value series for volatility: use payout or RTP series when available
      let values = [];

      // Support cascading mode: input can be an array representing one spin broken into cascades
      // Sum all cascade payouts (numbers or objects with totalPayout) into a single value per spin
      if (Array.isArray(spinResults)) {
        const sumFromArray = (arr) => {
          let sum = 0;
          for (let i = 0; i < arr.length; i++) {
            const entry = arr[i];
            if (typeof entry === 'number' && Number.isFinite(entry)) {
              sum += entry;
            } else if (Array.isArray(entry)) {
              sum += sumFromArray(entry);
            } else if (entry && typeof entry === 'object') {
              const payout = entry.totalPayout;
              if (typeof payout === 'number' && Number.isFinite(payout)) sum += payout;
            }
          }
          return sum;
        };
        const total = sumFromArray(spinResults);
        if (Number.isFinite(total)) values = [total];
      } else if (Array.isArray(spinResults.values)) {
        // Support both a single result and a series under RTPDataSeries / custom series
        values = spinResults.values.filter((v) => typeof v === 'number');
      } else if (Array.isArray(spinResults.RTPDataSeries)) {
        values = spinResults.RTPDataSeries.filter((v) => typeof v === 'number');
      } else if (Array.isArray(spinResults.payoutSeries)) {
        values = spinResults.payoutSeries.filter((v) => typeof v === 'number');
      } else if (Array.isArray(spinResults.totalPayouts)) {
        values = spinResults.totalPayouts.filter((v) => typeof v === 'number');
      } else if (Array.isArray(spinResults.cascades)) {
        // Also support objects that contain a cascades array
        const cascades = spinResults.cascades || [];
        let total = 0;
        for (let i = 0; i < cascades.length; i++) {
          const c = cascades[i];
          if (typeof c === 'number' && Number.isFinite(c)) total += c;
          else if (c && typeof c === 'object' && typeof c.totalPayout === 'number' && Number.isFinite(c.totalPayout))
            total += c.totalPayout;
          else if (Array.isArray(c)) {
            for (let j = 0; j < c.length; j++) {
              const e = c[j];
              if (typeof e === 'number' && Number.isFinite(e)) total += e;
              else if (
                e &&
                typeof e === 'object' &&
                typeof e.totalPayout === 'number' &&
                Number.isFinite(e.totalPayout)
              )
                total += e.totalPayout;
            }
          }
        }
        values = Number.isFinite(total) ? [total] : [];
      } else if (typeof spinResults.totalPayout === 'number') {
        values = [spinResults.totalPayout];
      }

      // Merge with retained values from previous runs
      const cumulativeValues = Array.isArray(this._internal.cumulativeValues)
        ? this._internal.cumulativeValues.slice()
        : [];
      if (values.length > 0) {
        for (let i = 0; i < values.length; i++) {
          const v = values[i];
          if (typeof v === 'number' && Number.isFinite(v)) {
            cumulativeValues.push(v);
          }
        }
      }

      const n = cumulativeValues.length;
      let mean = 0;
      let variance = 0;
      let standardDeviation = 0;

      if (n > 0) {
        mean = cumulativeValues.reduce((s, v) => s + v, 0) / n;
        if (n > 1) {
          const diffSquares = cumulativeValues.map((v) => {
            const d = v - mean;
            return d * d;
          });
          // Use sample variance (unbiased) with n-1; if n==1 fall back to 0
          variance = diffSquares.reduce((s, v) => s + v, 0) / (n - 1);
        } else {
          variance = 0;
        }
        standardDeviation = Math.sqrt(variance);
      }

      // Volatility in percentage: sigma divided by mean, times 100, when mean > 0
      let volatilityPercentage = 0;
      if (mean > 0) {
        volatilityPercentage = (standardDeviation / mean) * 100;
      } else if (standardDeviation > 0) {
        // If mean is 0 but there is spread, define as 100% for signaling high volatility
        volatilityPercentage = 100;
      }

      // Amplitude / Scaling factor: use peak-to-peak relative to mean if possible
      let amplitude = 0;
      if (n > 0) {
        const minV = Math.min.apply(null, cumulativeValues);
        const maxV = Math.max.apply(null, cumulativeValues);
        const peakToPeak = maxV - minV;
        amplitude = mean !== 0 ? peakToPeak / Math.abs(mean) : peakToPeak;
      }

      this._internal.results = {
        volatilityPercentage,
        standardDeviation,
        mean,
        variance,
        amplitude
      };

      // Persist the retained series
      this._internal.cumulativeValues = cumulativeValues;

      this._internal.inspectData = {
        count: n,
        mean,
        variance,
        standardDeviation,
        volatilityPercentage,
        amplitude
      };

      this.flagOutputDirty('volatilityResult');
      this.flagOutputDirty('standardDeviation');
      this.flagOutputDirty('mean');
      this.flagOutputDirty('variance');
      this.flagOutputDirty('amplitude');
      } finally {
        this.sendSignalOnOutput('Done');
      }
    }
  }

