{
    generateWeightedReels: function () {
      // Custom seeded random number generator (Linear Congruential Generator)
      function SeededRandom(seed) {
        this.seed = seed % 2147483647;
        if (this.seed <= 0) this.seed += 2147483646;
      }

      SeededRandom.prototype.next = function () {
        this.seed = (this.seed * 16807) % 2147483647;
        return this.seed;
      };

      SeededRandom.prototype.nextFloat = function () {
        return (this.next() - 1) / 2147483646;
      };

      SeededRandom.prototype.integer = function (min, max) {
        return Math.floor(this.nextFloat() * (max - min + 1)) + min;
      };

      // Weighted random selection function
      function selectWeightedSymbol(symbolWeights, seededRandom) {
        const totalWeight = symbolWeights.reduce((sum, weight) => sum + weight, 0);
        let randomValue = seededRandom.nextFloat() * totalWeight;

        for (let i = 0; i < symbolWeights.length; i++) {
          randomValue -= symbolWeights[i];
          if (randomValue <= 0) {
            return i + 1; // Symbol is index + 1
          }
        }

        // Fallback to last symbol if floating point errors occur
        return symbolWeights.length;
      }

      try {
        // Guard: if locked, don't regenerate
        if (this._reelStripsLocked && this._internal.reels.length > 0) {
          this.sendSignalOnOutput('Done');
          return;
        }

        const isDynamic = this._internal.isDynamic;

        if (isDynamic) {
          // Dynamic mode - generate matrix with weighted random symbols
          return this.generateDynamicReels();
        } else {
          // Static mode - use existing logic
          return this.generateStaticReels();
        }
      } catch (error) {
        console.error('Weighted Reels Error:', error.message);

        // Update inspect data with error
        this._internal.inspectData = {
          error: error.message,
          mode: this._internal.isDynamic ? 'dynamic' : 'static'
        };

        // Reset results
        this._internal.reels = [];
        this._internal.stopPosList = [];
        this._internal.isComplete = false;
        this.flagOutputDirty('reels');
        this.flagOutputDirty('stopPosList');

        // Still send complete signal on error
        this.sendSignalOnOutput('Done');
      }
    },

    generateFreeSpinWeightedReels: function () {
      try {
        // Guard: if locked, don't regenerate
        if (this._reelStripsLocked && this._internal.reels.length > 0) {
          this.sendSignalOnOutput('Done');
          return;
        }

        const isDynamic = this._internal.isDynamic;

        if (isDynamic) {
          // Dynamic mode - generate matrix with weighted random symbols and ensure free spin symbol placement
          return this.generateDynamicReelsWithFreeSpin();
        } else {
          // Static mode - ensure free spin symbol is part of the outcome
          return this.generateStaticReelsWithFreeSpin();
        }
      } catch (error) {
        console.error('Weighted Reels Error:', error.message);

        // Update inspect data with error
        this._internal.inspectData = {
          error: error.message,
          mode: this._internal.isDynamic ? 'dynamic' : 'static-free-spin'
        };

        // Reset results
        this._internal.reels = [];
        this._internal.stopPosList = [];
        this._internal.isComplete = false;
        this.flagOutputDirty('reels');
        this.flagOutputDirty('stopPosList');

        // Still send complete signal on error
        this.sendSignalOnOutput('Done');
      }
    },

    generateStaticReels: function () {
      // Custom seeded random number generator (Linear Congruential Generator)
      function SeededRandom(seed) {
        this.seed = seed % 2147483647;
        if (this.seed <= 0) this.seed += 2147483646;
      }

      SeededRandom.prototype.next = function () {
        this.seed = (this.seed * 16807) % 2147483647;
        return this.seed;
      };

      SeededRandom.prototype.nextFloat = function () {
        return (this.next() - 1) / 2147483646;
      };

      SeededRandom.prototype.integer = function (min, max) {
        return Math.floor(this.nextFloat() * (max - min + 1)) + min;
      };

      const reelStrips = this._internal.reelStrips;
      const seeds = this._internal.seeds;
      const rowSize = this._internal.rowSize;
      const inputStopPosList = this._internal.stopPosListInput || [];

      // Validate inputs
      if (!Array.isArray(reelStrips) || reelStrips.length === 0) {
        throw new Error('Reel strips array is required and cannot be empty');
      }

      // Check if all reel strips are arrays and have the same length
      if (!reelStrips.every((strip) => Array.isArray(strip))) {
        throw new Error('All reel strips must be arrays');
      }

      if (reelStrips.length === 0) {
        throw new Error('At least one reel strip is required');
      }

      const reelStripLength = reelStrips[0].length;
      if (reelStripLength === 0) {
        throw new Error('Reel strips cannot be empty');
      }

      if (!reelStrips.every((strip) => strip.length === reelStripLength)) {
        throw new Error('All reel strips must have the same length');
      }

      // Determine if provided stopPosList input is valid
      const useInputStops =
        Array.isArray(inputStopPosList) &&
        inputStopPosList.length === reelStrips.length &&
        inputStopPosList.every((pos) => Number.isInteger(pos) && pos >= 0 && pos < reelStripLength);

      // If not using input stops, validate seeds now
      if (!useInputStops) {
        if (!Array.isArray(seeds) || seeds.length < reelStrips.length) {
          throw new Error(`Seeds array must contain at least ${reelStrips.length} elements`);
        }
      }

      // Generate weighted reels
      const reels = [];
      const stopPosList = [];

      for (let idx = 0; idx < reelStrips.length; idx++) {
        const reelStrip = reelStrips[idx];
        const pointerPos = useInputStops
          ? inputStopPosList[idx]
          : new SeededRandom(seeds[idx]).integer(0, reelStripLength - 1);

        const reel = Array.from({ length: rowSize }, (_, i) => reelStrip[(pointerPos + i) % reelStripLength]);

        stopPosList.push(pointerPos);
        reels.push(reel);
      }

      // Store results
      this._internal.reels = reels;
      this._internal.stopPosList = stopPosList;
      this._internal.isComplete = true;

      // Update inspect data
      this._internal.inspectData = {
        mode: 'static',
        reelStrips: reelStrips,
        reelStripLength: reelStripLength,
        seeds: seeds,
        rowSize: rowSize,
        reels: reels,
        stopPosList: stopPosList,
        reelsCount: reels.length,
        stopPosSource: useInputStops ? 'input' : 'seeded',
        inputStopPosList: inputStopPosList
      };

      // Flag outputs as dirty
      this.flagOutputDirty('reels');
      this.flagOutputDirty('stopPosList');

      // Send complete signal
      this.sendSignalOnOutput('Done');
    },

    generateStaticReelsWithFreeSpin: function () {
      // Custom seeded random number generator (Linear Congruential Generator)
      function SeededRandom(seed) {
        this.seed = seed % 2147483647;
        if (this.seed <= 0) this.seed += 2147483646;
      }

      SeededRandom.prototype.next = function () {
        this.seed = (this.seed * 16807) % 2147483647;
        return this.seed;
      };

      SeededRandom.prototype.nextFloat = function () {
        return (this.next() - 1) / 2147483646;
      };

      SeededRandom.prototype.integer = function (min, max) {
        return Math.floor(this.nextFloat() * (max - min + 1)) + min;
      };

      const reelStrips = this._internal.reelStrips;
      const seeds = this._internal.seeds;
      const rowSize = this._internal.rowSize;
      const freeSpinSymbol = this._internal.freeSpinSymbol;
      const inputStopPosList = this._internal.stopPosListInput || [];

      // Validate inputs
      if (!Array.isArray(reelStrips) || reelStrips.length === 0) {
        throw new Error('Reel strips array is required and cannot be empty');
      }

      // Check if all reel strips are arrays and have the same length
      if (!reelStrips.every((strip) => Array.isArray(strip))) {
        throw new Error('All reel strips must be arrays');
      }

      if (reelStrips.length === 0) {
        throw new Error('At least one reel strip is required');
      }

      const reelStripLength = reelStrips[0].length;
      if (reelStripLength === 0) {
        throw new Error('Reel strips cannot be empty');
      }

      if (!reelStrips.every((strip) => strip.length === reelStripLength)) {
        throw new Error('All reel strips must have the same length');
      }

      // Determine if provided stopPosList input is valid
      const useInputStops =
        Array.isArray(inputStopPosList) &&
        inputStopPosList.length === reelStrips.length &&
        inputStopPosList.every((pos) => Number.isInteger(pos) && pos >= 0 && pos < reelStripLength);

      // If not using input stops, validate seeds now
      if (!useInputStops) {
        if (!Array.isArray(seeds) || seeds.length < reelStrips.length) {
          throw new Error(`Seeds array must contain at least ${reelStrips.length} elements`);
        }
      }

      // Generate weighted reels with free spin constraint
      const reels = [];
      const stopPosList = [];
      const freeSpinApplied = [];

      for (let idx = 0; idx < reelStrips.length; idx++) {
        const reelStrip = reelStrips[idx];
        let pointerPos;
        let usedFreeSpin = false;

        if (useInputStops) {
          pointerPos = inputStopPosList[idx];
        } else {
          const seededRandom = new SeededRandom(seeds[idx]);
          const freeSpinPositions = [];

          if (freeSpinSymbol !== null && freeSpinSymbol !== undefined) {
            for (let symbolIdx = 0; symbolIdx < reelStripLength; symbolIdx++) {
              if (reelStrip[symbolIdx] === freeSpinSymbol) {
                freeSpinPositions.push(symbolIdx);
              }
            }
          }

          if (freeSpinPositions.length > 0) {
            const selectedIndex =
              freeSpinPositions.length === 1
                ? freeSpinPositions[0]
                : freeSpinPositions[seededRandom.integer(0, freeSpinPositions.length - 1)];

            const freeSpinPos =
              (((selectedIndex - (rowSize - 1)) % reelStripLength) + reelStripLength) % reelStripLength;
            const rawPointerPos = seededRandom.integer(freeSpinPos, freeSpinPos + rowSize - 1);
            pointerPos = ((rawPointerPos % reelStripLength) + reelStripLength) % reelStripLength;
            usedFreeSpin = true;
          } else {
            pointerPos = seededRandom.integer(0, reelStripLength - 1);
          }
