        mode: 'static-free-spin',
        reelStrips: reelStrips,
        reelStripLength: reelStripLength,
        seeds: seeds,
        rowSize: rowSize,
        reels: reels,
        stopPosList: stopPosList,
        reelsCount: reels.length,
        stopPosSource: stopPosSource,
        inputStopPosList: inputStopPosList,
        freeSpinSymbol: freeSpinSymbol,
        freeSpinApplied: freeSpinApplied
