    },

    generateDynamicReelsWithFreeSpin: function () {
      // Validate inputs for dynamic mode
      const reelStrips = this._internal.reelStrips;
      const symbolWeights = this._internal.symbolWeights;
      const rowSize = this._internal.rowSize;
      const freeSpinSymbol = this._internal.freeSpinSymbol;
      const blockedReels = this._internal.blockedReels;

      if (!Array.isArray(reelStrips) || reelStrips.length === 0) {
        throw new Error('Reel strips array is required and cannot be empty to determine column size');
      }

      if (!Array.isArray(symbolWeights) || symbolWeights.length === 0) {
        throw new Error('Symbol weights array is required and cannot be empty for dynamic mode');
      }

      if (!symbolWeights.every((weight) => typeof weight === 'number' && weight > 0)) {
        throw new Error('All symbol weights must be positive numbers');
      }

      // If freeSpinSymbol is not a finite number, fall back to default dynamic reels
      if (!Number.isFinite(freeSpinSymbol)) {
        return this.generateDynamicReels();
      }

      if (typeof blockedReels !== 'string') {
        throw new Error('Blocked reels must be a valid comma-separated string');
      }

      // Empty/whitespace entries mean NO blocked reels — filter them out so an
      // empty blockedReels ("") yields [] instead of [0] (Number("") === 0).
      const blockedReelIndices = blockedReels
        .split(',')
        .map((idx) => idx.trim())
        .filter((idx) => idx.length > 0)
        .map((idx) => {
          const parsed = Number(idx);
          if (isNaN(parsed)) {
            throw new Error(`Invalid blocked reel index: "${idx}"`);
          }
          return parsed;
        });

      const columnSize = reelStrips.length;

      // Generate base reel using same logic as reel-strips-generator.js
      const baseReel = [];
      const minWeight = Math.min(...symbolWeights);
      const symbolWeightsRelativeToMin = symbolWeights.map((weight) => Math.ceil(weight / minWeight));

      for (let i = 1; i <= symbolWeights.length; i++) {
        baseReel.push(...Array(symbolWeightsRelativeToMin[i - 1]).fill(i));
      }

      // Build a base reel that excludes the free spin symbol to ensure a single occurrence per reel
      const baseReelWithoutFreeSpin = baseReel.filter((symbol) => symbol !== freeSpinSymbol);
      const fallbackReel = baseReelWithoutFreeSpin.length > 0 ? baseReelWithoutFreeSpin : baseReel;

      // PROVABLY FAIR (2026-06-23): seed per-column from the Seeds input (ISAAC) so
      // dynamic free-spin outcomes are reproducible/auditable. The static paths use
      // a seeded LCG; this one used Math.random(). Falls back to Math.random() when
      // seeds aren't wired (one per column), so no regression for seedless games.
      function SeededRandom(seed) {
        this.seed = seed % 2147483647;
        if (this.seed <= 0) this.seed += 2147483646;
      }
      SeededRandom.prototype.next = function () {
        this.seed = (this.seed * 16807) % 2147483647;
        return this.seed;
      };
      SeededRandom.prototype.nextFloat = function () {
        return (this.next() - 1) / 2147483646;
      };
      const seeds = this._internal.seeds;
      const haveSeeds = Array.isArray(seeds) && seeds.length >= columnSize;

      const reels = [];
      const freeSpinRows = [];
      const blockedSet = new Set(blockedReelIndices);

      for (let col = 0; col < columnSize; col++) {
        const reel = [];
        const colRng = haveSeeds ? new SeededRandom(seeds[col]) : null;
        const rnd = () => (colRng ? colRng.nextFloat() : Math.random());

        if (blockedSet.has(col)) {
          for (let row = 0; row < rowSize; row++) {
            const randomBaseReelIndex = Math.floor(rnd() * baseReel.length);
            const symbol = baseReel[randomBaseReelIndex];
            reel.push(symbol);
          }
          freeSpinRows.push(null);
        } else {
          const freeSpinRow = Math.floor(rnd() * rowSize);
          freeSpinRows.push(freeSpinRow);

          for (let row = 0; row < rowSize; row++) {
            if (row === freeSpinRow) {
              reel.push(freeSpinSymbol);
            } else {
              const randomBaseReelIndex = Math.floor(rnd() * fallbackReel.length);
              const symbol = fallbackReel[randomBaseReelIndex];
              reel.push(symbol);
            }
          }
        }

        reels.push(reel);
      }

      // Store results
      this._internal.reels = reels;
      this._internal.stopPosList = []; // No stop positions in dynamic mode
      this._internal.isComplete = true;

      // Update inspect data
      this._internal.inspectData = {
        mode: 'dynamic-free-spin',
        symbolWeights: symbolWeights,
        symbolWeightsRelativeToMin: symbolWeightsRelativeToMin,
        baseReel: baseReel,
        baseReelLength: baseReel.length,
        baseReelWithoutFreeSpinLength: fallbackReel.length,
        internalRandomSeeds: [], // No internal random seeds in dynamic mode
        rowSize: rowSize,
        columnSize: columnSize,
        totalCells: rowSize * columnSize,
        reels: reels,
        reelsCount: reels.length,
        freeSpinSymbol: freeSpinSymbol,
        blockedReels: blockedReels,
        blockedReelIndices: blockedReelIndices,
        freeSpinRows: freeSpinRows
      };

      // Flag outputs as dirty
      this.flagOutputDirty('reels');
      this.flagOutputDirty('stopPosList');

      // Send complete signal
      this.sendSignalOnOutput('Done');
    },

    generateDynamicReels: function () {
      // Custom seeded random number generator (Linear Congruential Generator)
      function SeededRandom(seed) {
        this.seed = seed % 2147483647;
        if (this.seed <= 0) this.seed += 2147483646;
