          editorName: nameWithTab('Border Style'),
          group: 'Border Style',
          allowVisualStates: true,
          type: {
            name: 'enum',
            enums: [
              { label: 'None', value: 'none' },
              { label: 'Solid', value: 'solid' },
              { label: 'Dotted', value: 'dotted' },
