    if (frame.position) NodeSharedPortDefinitions.addTransformInputs(def);
    if (frame.margins) NodeSharedPortDefinitions.addMarginInputs(def);
    if (frame.padding) NodeSharedPortDefinitions.addPaddingInputs(def);
