      function _updatePorts() {
        var ports = [];

        if (node.parameters['path'] !== undefined) {
          var inputs = node.parameters['path'].match(/\{[A-Za-z0-9_]*\}/g) || [];
          var portsNames = inputs.map(function (def) {
            return def.replace('{', '').replace('}', '');
