          const urlPath = pageNode.parameters.urlPath;
          if (typeof urlPath === 'string') {
            const matches = urlPath.match(/\{([^}]+)\}/g);
            if (matches) {
              matches.forEach((m) => {
                const varName = m.replace('{', '').replace('}', '').trim();
                if (varName) uniqueNames[varName] = true;
              });
            }
          }
