function updatePorts(nodeId, parameters, editorConnection) {
  var ports = [];

  // Add payload inputs
  var payload = parameters.payload;
  if (payload) {
    payload = payload.split(',');
    for (const p of payload) {
      ports.push({
        type: {
          name: '*',
          allowConnectionsOnly: true
        },
        plug: 'input',
        group: 'Payload',
        name: p,
        displayName: p
      });
    }
  }

  editorConnection.sendDynamicPorts(nodeId, ports, {
    detectRenamed: {
      plug: 'input'
    }
  });
}

